insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'goal', 'תחושת ביטחון במרחב', 'להרגיש מוגן/ת במרכז: לדעת איפה אני, מי שומר עליי ולאן אפשר לפנות', array['ביטחון ויציבות']::text[], 'ביטחון ויציבות', array['ARC', 'NMT', 'ויסות חושי']::text[], '{"bank": 1, "review": 3, "scale": ["דרוך/ה ומבוהל/ת רוב היום", "נרגע/ת רק כשמבוגר צמוד", "נרגע/ת במקומות מוכרים", "נע/ה בחופשיות ברוב המרחב", "רגוע/ה ובטוח/ה גם במצבים חדשים"], "avoid": "לא להפתיע מאחור ולא לגעת בלי לומר קודם", "strengths": ["אומץ", "סקרנות"], "skills": ["פנייה למבוגר", "שימוש בפינה השקטה"], "ages": {"2-5": {"targets": "נכנס/ת לחדר המשחקים ונשאר/ת בו 10 דקות עם מבוגר בקרבת מקום, ב-4 מתוך 5 ימים בשבוע", "steps": ["כשהילד/ה נצמד/ת או בוכה בכניסה לחדר ← מתכופפים לגובה העיניים, נותנים יד ונכנסים יחד", "כשנשמע רעש חזק ← מתקרבים, מסבירים במילה אחת מה היה ומחבקים אם הילד/ה רוצה"], "principles": "קודם גוף רגוע ומבוגר קרוב, אחר כך מילים", "sentences": ["אני כאן איתך", "פה שומרים עליך"], "seen": "נבהל/ת מרעשים, נצמד/ת למבוגר ומסרב/ת להיכנס למקומות חדשים", "needs": "חוויה חוזרת של מבוגר זמין שמגן ומרגיע", "why": "בגיל הזה ויסות נבנה דרך מבוגר מווסת; בלי תחושת ביטחון בסיסית מערכת ההישרדות פעילה והלמידה נעצרת", "why_staff": "ילד/ה שמרגיש/ה בטוח/ה יכול/ה לשחק, ללמוד ולהירגע מהר יותר", "method": "NMT: ויסות לפני קשר ולפני חשיבה"}, "5-8": {"targets": "מסתובב/ת בחללים המוכרים בלי ליווי צמוד, ופונה למבוגר כשמשהו מפחיד, ב-4 מתוך 5 ימים בשבוע", "steps": ["כשהילד/ה בודק/ת כל הזמן איפה המבוגר ← אומרים מראש איפה נהיה ומתי נחזור, ומקיימים", "כשנכנסים לחדר חדש ← מראים את הדלת, את הפינה השקטה ומי נמצא שם"], "principles": "ניבוי וקביעות: אותם מבוגרים, אותם מקומות, אותן מילים", "sentences": ["רואים שזה חדש. בוא/י נראה יחד מה יש פה", "אם יהיה לך קשה, אפשר לבוא אליי"], "seen": "סורק/ת את החדר, שואל/ת שוב ושוב מי יהיה במשמרת, מתקשה להתרכז במשחק", "needs": "מפה ברורה של המקום ושל המבוגרים, והוכחה שהם חוזרים", "why": "דריכות יתר היא תגובה הסתגלותית לסכנה שהייתה; ניבוי ועקביות מורידים עוררות ומאפשרים חקירה", "why_staff": "כשהילד/ה יודע/ת מה יקרה ומי שומר, הגוף נרגע וההתנהגות משתפרת", "method": "ARC – התקשרות: עקביות ושגרות של מבוגר"}, "8-12": {"targets": "אומר/ת במילים כשמשהו במרחב מרגיש לא בטוח (ולא בורח/ת או תוקף/ת), לפחות 3 פעמים בשבוע, תוך 3 חודשים", "steps": ["כשהילד/ה נראה/ית דרוך/ה או מתנגד/ת ← שואלים בשקט מה מרגיש לא בטוח עכשיו, ומציעים מקום לשבת", "כשהוא/היא מספר/ת מה מפריע ← מתייחסים ברצינות ובודקים יחד מה אפשר לשנות"], "principles": "הבחירה והשליטה הן חלק מהביטחון: מציעים אפשרויות ולא רק הוראות", "sentences": ["מה יעזור לך להרגיש בטוח/ה יותר כרגע?", "זה הגיוני שאחרי מה שעברת הגוף נזהר"], "seen": "מגיב/ה בתוקפנות או בהתרחקות כשמשהו לא צפוי, מתקשה לבטוח במבוגרים חדשים", "needs": "תחושת שליטה, הסבר על מה שקורה, ומבוגרים שמחזיקים את המילה", "why": "בגיל הזה אפשר לבנות מודעות לטריגרים ולהבחין בין סכנה של אז לבטוח של עכשיו", "why_staff": "כשהילד/ה יכול/ה להגיד מה מפחיד, אפשר לעזור לפני שזה מתפרץ", "method": "TF-CBT: פסיכו-חינוך על תגובות טראומה"}}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, draft = true where public.mercury_library.content is null;
insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'goal', 'ניבוי והכנה מראש', 'לדעת מה עומד לקרות, ולהתמודד טוב יותר עם מה שמגיע', array['ביטחון ויציבות', 'מעברים ושגרה']::text[], 'ביטחון ויציבות', array['ARC', 'ויסות חושי']::text[], '{"bank": 1, "review": 1, "scale": ["כל שינוי מוביל להתפרצות", "נרגע/ת רק אחרי זמן ארוך", "מקבל/ת שינוי כשמכינים מראש", "משתמש/ת בלוח היום לבד", "שואל/ת ומתכנן/ת בעצמו/ה"], "avoid": "לא להודיע על שינוי ברגע האחרון כשאפשר להכין מראש", "strengths": ["סבלנות", "גמישות"], "skills": ["מעבר בלי התפרצות"], "ages": {"2-5": {"targets": "עובר/ת לפעילות הבאה אחרי תזכורת ותמונה, בלי בכי ממושך, ב-3 מתוך 5 מעברים ביום", "steps": ["5 דקות לפני מעבר ← מראים את התמונה של הפעילות הבאה ואומרים עוד מעט", "כשהילד/ה מתנגד/ת ← נותנים חפץ מעבר קטן ושרים שיר מעבר קבוע"], "principles": "מעט מילים, הרבה תמונות וטקסים קבועים", "sentences": ["עוד מעט נגמר ואז הולכים לאכול", "קודם משחק, אחר כך מקלחת"], "seen": "בוכה או נזרק/ת לרצפה כשמפסיקים פעילות", "needs": "תחושה שהעולם צפוי וטקס שמחבר בין פעילויות", "why": "פעוטות עם טראומה חווים שינוי פתאומי כאיום; טקס מעבר מספק ויסות חיצוני", "why_staff": "כשיודעים מה מגיע, קל יותר לעזוב את מה שעושים עכשיו", "method": "ARC – ויסות: שגרות וטקסים מווסתים"}, "5-8": {"targets": "בודק/ת בלוח היום מה הלאה ומתכונן/ת למעבר, ב-4 מתוך 5 ימים בשבוע", "steps": ["בבוקר ← עוברים יחד על לוח היום ומסמנים מה מחכה", "כשיש שינוי לא צפוי ← מודיעים מוקדם ככל האפשר, מסבירים למה ונותנים בחירה קטנה"], "principles": "מכינים, מזכירים, ונותנים לילד/ה תפקיד במעבר", "sentences": ["בוא/י נבדוק בלוח מה עכשיו", "היום יש שינוי קטן. רציתי שתדע/י לפני"], "seen": "שואל/ת שוב ושוב מה עכשיו, נבהל/ת משינויים קטנים", "needs": "כלי חיצוני שמראה את היום ומבוגר שמודיע מראש", "why": "כלי ניבוי חיצוניים מפחיתים חרדה ומפנים משאבים קוגניטיביים לוויסות", "why_staff": "לוח יום ברור חוסך הרבה התפרצויות", "method": "ARC – ויסות: מבנה וצפיות"}, "8-12": {"targets": "מתמודד/ת עם שינוי בתוכנית בלי להתפרץ (אומר/ת מה קשה או מבקש/ת זמן), ב-3 מתוך 4 שינויים בשבוע", "steps": ["כשמשהו משתנה ← מסבירים את הסיבה, מודים שזה מאכזב ושואלים מה יעזור", "פעם בשבוע ← מתכננים יחד את השבוע ומסמנים מה יכול להשתנות"], "principles": "שקיפות וכבוד: מסבירים כמו לבן/בת שיח, לא רק מודיעים", "sentences": ["זה באמת מעצבן שהתוכנית השתנתה", "מה הדבר הכי קשה לך בשינוי הזה?"], "seen": "מגיב/ה בכעס עז לשינויים, חווה אותם כבגידה", "needs": "תחושת שליטה ושותפות בתכנון", "why": "שינוי לא צפוי מעורר חוויות של אובדן שליטה; שותפות בתכנון מחזקת סוכנות ואמון", "why_staff": "כשהילד/ה שותף/ה בתכנון, הוא/היא סומך/ת יותר על המבוגרים", "method": "ARC – מסוגלות: בחירה ושליטה"}}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, draft = true where public.mercury_library.content is null;
insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'goal', 'פנייה למבוגר בטוח', 'לזהות מבוגר שאפשר לסמוך עליו ולפנות אליו כשקשה', array['ביטחון ויציבות', 'היקשרות וקשר עם מבוגר']::text[], 'ביטחון ויציבות', array['ARC', 'DDP/PACE', 'Theraplay']::text[], '{"bank": 1, "review": 3, "scale": ["לא פונה בכלל, נסגר/ת או מתפרץ/ת", "פונה רק כשמבוגר מתקרב", "פונה למבוגר אחד מוכר", "פונה לכמה מבוגרים מוכרים", "פונה בזמן ובמילים לבד"], "avoid": "לא להעניש על פנייה בדרך לא נעימה, אלא לחזק את עצם הפנייה", "strengths": ["בקשת עזרה", "אומץ"], "skills": ["בקשת עזרה"], "ages": {"2-5": {"targets": "בא/ה למבוגר מוכר כשנפגע/ת או נבהל/ת (ולא מסתתר/ת), ב-3 מתוך 5 פעמים", "steps": ["כשהילד/ה נפגע/ת ← ניגשים מיד, מרגיעים בגוף ובקול ומשקפים: נפלת וכאב לך", "כשהילד/ה בא/ה בעצמו/ה ← מקבלים בחום ואומרים: טוב שבאת אליי"], "principles": "כל פנייה מקבלת מענה חם, גם כשהיא מגיעה בבכי או בצעקה", "sentences": ["טוב שבאת אליי", "כשכואב, אפשר לבוא אליי"], "seen": "מסתתר/ת או ממשיך/ה לשחק כשנפגע/ת, לא מצפה לנחמה", "needs": "ניסיון חוזר שמבוגר מנחם באמת", "why": "ילדים שחוו הזנחה לומדים לא לסמן מצוקה; מענה עקבי בונה מחדש ציפייה לנחמה", "why_staff": "ילד/ה שלומד/ת לבוא אלינו, מקבל/ת עזרה מהר יותר", "method": "Theraplay: טיפוח וקרבה של מבוגר"}, "5-8": {"targets": "פונה למבוגר במילים או בסימן מוסכם כשקשה, ב-3 מתוך 5 מצבי קושי בשבוע", "steps": ["קובעים יחד סימן לבקשת עזרה (כרטיס, יד על הכתף) ← מתרגלים אותו במשחק", "כשהילד/ה משתמש/ת בסימן ← עונים מיד ומחזקים: ראיתי שביקשת עזרה"], "principles": "הדרך לבקש עזרה צריכה להיות קלה יותר מהתפרצות", "sentences": ["ראיתי שביקשת עזרה, זה חכם", "אני פה. מה קרה?"], "seen": "מתפרץ/ת במקום לבקש, או מנסה להסתדר לבד עד שזה נשבר", "needs": "דרך פשוטה ובטוחה לסמן מצוקה ומבוגר שתמיד מגיב", "why": "פנייה לעזרה היא מיומנות התקשרותית שנבנית בחזרות מוצלחות", "why_staff": "סימן קבוע עוזר לילד/ה לבקש עזרה לפני שזה מתפוצץ", "method": "ARC – התקשרות: היענות של מבוגר"}, "8-12": {"targets": "בוחר/ת לפחות שני מבוגרים קבועים ופונה אליהם בעצמו/ה כשקשה, לפחות פעמיים בשבוע", "steps": ["משוחחים עם הילד/ה ← מי המבוגרים שהוא/היא סומך/ת עליהם ולמה", "כשהילד/ה מספר/ת משהו קשה ← מקשיבים עד הסוף לפני שמייעצים, ומודים על האמון"], "principles": "אמון נבנה כשהמבוגר מקשיב, לא שופט ומחזיק את מה שהבטיח", "sentences": ["תודה שסיפרת לי. זה לא קל", "מה היית רוצה שאעשה עם מה שסיפרת?"], "seen": "בודק/ת את המבוגרים בהתנהגות מאתגרת, מתקשה לבטוח", "needs": "מבוגרים שעומדים בבדיקות ונשארים", "why": "בגיל הזה הילד/ה בוחן/ת האם המבוגר אמין; עמידה בבדיקה מתקנת מודל עבודה פנימי", "why_staff": "כשהילד/ה בוחר/ת בנו ומספר/ת, זה סימן לאמון שנבנה", "method": "DDP/PACE: סקרנות ואמפתיה בשיחה"}}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, draft = true where public.mercury_library.content is null;
insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'goal', 'התמודדות עם תזכורות לטראומה', 'לזהות מה מעורר את הפחד ולהשתמש בדרך שעוזרת לחזור לכאן ועכשיו', array['ביטחון ויציבות', 'ויסות רגשי']::text[], 'ביטחון ויציבות', array['TF-CBT', 'ARC', 'ויסות חושי']::text[], '{"bank": 1, "review": 3, "scale": ["מוצף/ת לגמרי ולא ניתן לגשת", "נרגע/ת רק אחרי זמן ארוך עם מבוגר", "נרגע/ת עם מבוגר בעזרת כלי מוכר", "משתמש/ת בכלי עם תזכורת", "מזהה ומשתמש/ת בכלי לבד"], "avoid": "לא לחקור על מה שקרה ברגע של הצפה; קודם מרגיעים", "strengths": ["אומץ", "שליטה עצמית"], "skills": ["הירגעות בעזרת כלי"], "ages": {"2-5": {"targets": "נרגע/ת תוך 10 דקות עם מבוגר וחפץ מרגיע אחרי רגע של בהלה, ב-3 מתוך 5 פעמים", "steps": ["כשהילד/ה נבהל/ת פתאום (מקול, מריח, ממגע) ← מורידים גירויים, מתקרבים לאט ומדברים בקול רך", "אחרי שנרגע/ת ← משחקים יחד משחק מוכר ומרגיע"], "principles": "לא מסבירים ולא שואלים; מרגיעים את הגוף", "sentences": ["את/ה בטוח/ה עכשיו", "אני כאן, זה עובר"], "seen": "קפיאה, בכי חזק או תוקפנות פתאומית בלי סיבה נראית", "needs": "מבוגר שמזהה את הבהלה ומרגיע בלי לשאול", "why": "בגיל הזה התגובה היא גופית; ויסות משותף הוא הכלי המרכזי", "why_staff": "לפעמים משהו קטן מזכיר לילד/ה פחד ישן. מרגיעים קודם, מבינים אחר כך", "method": "ויסות חושי: הורדת גירויים ומגע מרגיע"}, "5-8": {"targets": "משתמש/ת בכלי הרגעה (נשימה, חפץ, פינה) עם תזכורת של מבוגר כשמשהו מבהיל, ב-3 מתוך 5 פעמים", "steps": ["מכינים יחד קופסת הרגעה אישית ← מתרגלים בזמנים רגועים", "כשמתחילה בהלה ← מזכירים במילה אחת את הכלי ועושים אותו יחד"], "principles": "מתרגלים כשרגוע, משתמשים כשקשה", "sentences": ["בוא/י נעשה את הנשימה של הבלון", "תסתכל/י סביב: מה את/ה רואה עכשיו?"], "seen": "מתפרץ/ת או בורח/ת במצבים שמזכירים את מה שקרה", "needs": "כלים מוכרים לחזרה לכאן ועכשיו", "why": "עיגון בהווה (grounding) מחזק את ההבחנה בין זיכרון לבין המצב הנוכחי", "why_staff": "כלי שתרגלנו ברוגע יעבוד גם ברגע קשה", "method": "TF-CBT: מיומנויות הרגעה ועיגון"}, "8-12": {"targets": "מזהה לפחות 2 דברים שמעוררים אותו/ה ומבקש/ת הפסקה או כלי לפני הצפה, לפחות פעמיים בשבוע", "steps": ["בשיחה רגועה ← עושים יחד רשימה של מה מקפיץ ומה עוזר", "כשהילד/ה מבקש/ת הפסקה ← מאשרים מיד ומחזקים את הזיהוי"], "principles": "הילד/ה הוא/היא המומחה/ית לגוף שלו/ה; אנחנו שותפים", "sentences": ["שמתי לב שזה קשה לך. מה יעזור עכשיו?", "זה זיכרון שמרגיש כמו עכשיו, אבל עכשיו את/ה כאן ובטוח/ה"], "seen": "מבין/ה בדיעבד שמשהו הקפיץ, אך מתקשה לעצור בזמן", "needs": "מודעות לטריגרים ורשות לבקש הפסקה", "why": "זיהוי טריגרים ותגובה מוקדמת מחזקים תחושת שליטה ומפחיתים הימנעות", "why_staff": "ילד/ה שמזהה מה מקפיץ אותו/ה יכול/ה לעצור לפני שזה מתפוצץ", "method": "TF-CBT: פסיכו-חינוך וזיהוי טריגרים"}}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, draft = true where public.mercury_library.content is null;
insert into public.mercury_library (scope, kind, title, description, themes, category, content, draft) values ('mercury', 'avoid', 'ממה להימנע – ביטחון', 'לא להודיע על שינויים ברגע האחרון. לא להבטיח מה שלא בטוח שיקרה. לא לאיים בהעברה או בעונש שמערער ביטחון.', array['ביטחון ויציבות']::text[], 'ביטחון ויציבות', '{"bank": 1, "ages": {"2-5": "לא להרים את הקול ולא לגשת מאחור בהפתעה. לא להשאיר את הילד/ה לבד בחדר חדש. לא לנתק מחפץ מעבר.", "5-8": "לא להודיע על שינויים ברגע האחרון. לא להבטיח מה שלא בטוח שיקרה. לא לאיים בהעברה או בעונש שמערער ביטחון.", "8-12": "לא לחקור על העבר כשלא ביקש/ה. לא לגעת בלי לשאול. לא להבטיח סודיות כשאי אפשר, ולא לשבור הבטחה."}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, draft = true where public.mercury_library.content is null;
insert into public.mercury_library (scope, kind, title, description, themes, category, content, draft) values ('mercury', 'signs', 'אותות מוקדמים – ביטחון', 'סורק/ת את החדר, שואל/ת שוב ושוב מי במשמרת, מתעצבן/ת מהר, לא מצליח/ה לשבת.', array['ביטחון ויציבות']::text[], 'ביטחון ויציבות', '{"bank": 1, "ages": {"2-5": "נצמד/ת למבוגר, מוצץ/ת אצבע, מפסיק/ה לשחק, קופא/ת במקום או מסתתר/ת.", "5-8": "סורק/ת את החדר, שואל/ת שוב ושוב מי במשמרת, מתעצבן/ת מהר, לא מצליח/ה לשבת.", "8-12": "שקט/ה ומרוחק/ת פתאום או דרוך/ה ועוקצני/ת, בודק/ת דלתות, מסרב/ת לכל בקשה."}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, draft = true where public.mercury_library.content is null;
insert into public.mercury_library (scope, kind, title, description, themes, category, content, draft) values ('mercury', 'calm', 'מה עוזר להירגע – ביטחון', 'פינה שקטה עם כרית ושמיכה, לראות את לוח היום, לשבת ליד מבוגר מוכר. משפט: את/ה בטוח/ה, אני פה איתך.', array['ביטחון ויציבות']::text[], 'ביטחון ויציבות', '{"bank": 1, "ages": {"2-5": "מבוגר קרוב בגובה העיניים, קול רך, שמיכה או בובה מוכרת, נדנוד עדין. משפט: אני כאן איתך, פה שומרים עליך.", "5-8": "פינה שקטה עם כרית ושמיכה, לראות את לוח היום, לשבת ליד מבוגר מוכר. משפט: את/ה בטוח/ה, אני פה איתך.", "8-12": "לבחור מקום לשבת, לשתות מים, הסבר קצר על מה שקורה, זמן לבד בטווח ראייה. משפט: מה יעזור לך להרגיש בטוח/ה יותר עכשיו?"}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, draft = true where public.mercury_library.content is null;
insert into public.mercury_library (scope, kind, title, description, themes, category, content, draft) values ('mercury', 'routine', 'שגרה – ביטחון', 'לוח יום בתמונות בגובה העיניים. סבב קבוע של מי מכניס לישון. הודעה מראש על חילופי משמרת.', array['ביטחון ויציבות']::text[], 'ביטחון ויציבות', '{"bank": 1, "ages": {"2-5": "אותו מבוגר בכניסה ובשינה כשאפשר. טקס בוקר וטקס לילה קבועים. חפץ מעבר תמיד בהישג יד.", "5-8": "לוח יום בתמונות בגובה העיניים. סבב קבוע של מי מכניס לישון. הודעה מראש על חילופי משמרת.", "8-12": "תכנון שבועי משותף. מבוגר קבוע לשיחה יומית קצרה. מקום אישי לחפצים שאיש לא נוגע בו."}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, draft = true where public.mercury_library.content is null;
insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'plan', 'תכנית: ביטחון ויציבות', '[שם] הגיע/ה למרכז [מתי]. כרגע הכי חשוב ש[שם] ירגיש/תרגיש בטוח/ה: מבוגרים קבועים, יום צפוי והכנה מראש לכל שינוי. [מה כבר עוזר].', array['ביטחון ויציבות']::text[], 'ביטחון ויציבות', array['ARC', 'NMT']::text[], '{"bank": 1, "summary": "[שם] הגיע/ה למרכז [מתי]. כרגע הכי חשוב ש[שם] ירגיש/תרגיש בטוח/ה: מבוגרים קבועים, יום צפוי והכנה מראש לכל שינוי. [מה כבר עוזר].", "goal_titles": ["תחושת ביטחון במרחב", "ניבוי והכנה מראש", "שימוש בכלי הרגעה"], "parts": {"avoid": "ממה להימנע – ביטחון", "signs": "אותות מוקדמים – ביטחון", "calm": "מה עוזר להירגע – ביטחון", "routine": "שגרה – ביטחון"}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, draft = true where public.mercury_library.content is null;
insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'goal', 'זיהוי ושיום רגשות', 'לזהות מה אני מרגיש/ה ולתת לזה שם', array['ויסות רגשי', 'זהות ודימוי עצמי']::text[], 'ויסות רגשי', array['ARC', 'TF-CBT', 'DDP/PACE']::text[], '{"bank": 1, "review": 3, "scale": ["לא מזהה רגשות, רק מתפרץ/ת או נסגר/ת", "מזהה רגש כשמבוגר משקף", "בוחר/ת רגש מתוך תמונות או אפשרויות", "אומר/ת רגש בסיסי במילים", "מתאר/ת רגש, עוצמה וסיבה"], "avoid": "לא לומר אין סיבה לבכות או תירגע/י, אלא לשקף את הרגש", "strengths": ["כנות", "אומץ"], "skills": ["מציאת מילים ברגע של קושי"], "ages": {"2-5": {"targets": "מצביע/ה על פרצוף רגש בכרטיס כשמבוגר שואל איך מרגישים, ב-3 מתוך 5 פעמים ביום", "steps": ["כשהילד/ה בוכה או כועס/ת ← משקפים במילה אחת: כועס, עצוב, מפחד", "בזמן משחק ← משחקים בבובות שמרגישות רגשות ונותנים להן שמות"], "principles": "המבוגר שם מילים על מה שהגוף מראה", "sentences": ["נראה לי שאת/ה עצוב/ה", "כועסים כשלוקחים לנו משהו"], "seen": "מבטא/ת רגשות רק בגוף: בכי, נשיכה, הכאה", "needs": "מבוגר שמתרגם את הגוף למילים", "why": "שיום רגש (affect labeling) מפחית עוררות ומניח בסיס לוויסות עצמי", "why_staff": "כשנותנים שם לרגש, הוא נהיה פחות מפחיד ואפשר להרגיע אותו", "method": "ARC – ויסות: זיהוי רגשות"}, "5-8": {"targets": "אומר/ת במילים רגש אחד לפחות ברגע של קושי (במקום להכות או לצעוק), ב-3 מתוך 5 מצבים בשבוע", "steps": ["כשהילד/ה מתחיל/ה להתעצבן ← מציעים מד רגשות ושואלים איפה הוא/היא עכשיו", "בסוף היום ← משחקים מה הרגשתי היום בעזרת כרטיסים"], "principles": "כל רגש מותר, לא כל התנהגות", "sentences": ["מותר לכעוס. לא מותר להכות", "איזה רגש יש לך עכשיו בגוף?"], "seen": "מתפרץ/ת ואחר כך לא יודע/ת להסביר מה קרה", "needs": "אוצר מילים רגשי וכלי פשוט למדוד עוצמה", "why": "חיבור בין תחושות גופניות למילים מחזק את הקשר בין המערכת הרגשית לחשיבה", "why_staff": "ילד/ה שיכול/ה להגיד כועס/ת, צריך/ה פחות להראות את זה בידיים", "method": "TF-CBT: מיומנויות זיהוי והבעה רגשית"}, "8-12": {"targets": "מתאר/ת במילים רגש, עוצמה (1–5) וסיבה אחרי אירוע קשה, לפחות 3 פעמים בשבוע", "steps": ["אחרי שנרגע/ת ← עושים יחד שרשרת: מה קרה, מה הרגשתי, מה עשיתי", "מדי פעם ← שואלים בסקרנות, בלי שיפוט, על רגשות מעורבים"], "principles": "סקרנות וקבלה: מנסים להבין יחד, לא לתקן", "sentences": ["אפשר להרגיש גם כעס וגם עצב באותו רגע", "בסולם מ-1 עד 5, כמה חזק זה היה?"], "seen": "מכחיש/ה רגשות או מתאר/ת רק כעס", "needs": "רשות להרגיש רגשות פגיעים יותר מכעס", "why": "הבחנה בין רגשות ומדידת עוצמה מאפשרות התאמה של אסטרטגיית ויסות", "why_staff": "מאחורי הכעס יש לפעמים עצב או פחד. כשהילד/ה מגלה את זה, קל יותר לעזור", "method": "DDP/PACE: סקרנות וקבלה של חוויה פנימית"}}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, draft = true where public.mercury_library.content is null;
insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'goal', 'שימוש בכלי הרגעה', 'להשתמש בדרך הרגעה שבחרתי, לבד או עם מבוגר', array['ויסות רגשי']::text[], 'ויסות רגשי', array['ARC', 'ויסות חושי', 'NMT', 'TF-CBT']::text[], '{"bank": 1, "review": 1, "scale": ["לא נרגע/ת גם עם עזרה", "נרגע/ת רק עם מבוגר ואחרי זמן ארוך", "משתמש/ת בכלי כשמבוגר מציע", "בוחר/ת כלי בעצמו/בעצמה עם תזכורת", "משתמש/ת בכלי לבד, בזמן"], "avoid": "לא לשלוח לפינה השקטה כעונש; זו פינה של הרגעה", "strengths": ["שליטה עצמית", "התמדה"], "skills": ["הירגעות בעזרת כלי"], "ages": {"2-5": {"targets": "נרגע/ת תוך 5–10 דקות עם מבוגר וכלי מוכר (חיבוק, שמיכה, שיר), ב-3 מתוך 5 פעמים", "steps": ["כשהילד/ה מוצף/ת ← מתיישבים לידו/לידה, מורידים את הקול ומציעים את הכלי האהוב", "בזמנים רגועים ← משחקים בנשיפה של נוצה ובחיבוק דוב"], "principles": "ויסות משותף: המבוגר רגוע, הגוף של הילד/ה לומד ממנו", "sentences": ["בוא/י נשב פה יחד", "נושפים לאט, כמו על נר"], "seen": "בוכה זמן רב, לא מצליח/ה להירגע לבד", "needs": "מבוגר מווסת וכלים חושיים פשוטים", "why": "ויסות עצמי מתפתח מתוך חוויות חוזרות של ויסות משותף", "why_staff": "כשאנחנו רגועים לידו/לידה, הגוף של הילד/ה נרגע מהר יותר", "method": "NMT: ויסות דרך גוף וקצב"}, "5-8": {"targets": "בוחר/ת כלי מתוך קופסת ההרגעה ומשתמש/ת בו עם תזכורת, ב-3 מתוך 5 מצבי קושי בשבוע", "steps": ["מכינים יחד קופסה אישית (כדור לחיץ, תמונה, מוזיקה) ← מתרגלים בזמן רגוע", "כשמתחיל קושי ← מראים את הקופסה בלי הרבה מילים ומחכים"], "principles": "הבחירה אצל הילד/ה; המבוגר מזכיר ומחכה", "sentences": ["איזה כלי יעזור לך עכשיו?", "אני מחכה פה עד שתרגיש/תרגישי טוב יותר"], "seen": "יודע/ת על הכלים אבל שוכח/ת אותם כשקשה", "needs": "תרגול חוזר ותזכורת חזותית", "why": "כלים שתורגלו בעוררות נמוכה זמינים יותר בעוררות גבוהה", "why_staff": "כלי שבחר/ה בעצמו/בעצמה עובד יותר טוב מכלי שקיבל/ה", "method": "ויסות חושי: קופסת כלים אישית"}, "8-12": {"targets": "משתמש/ת בכלי הרגעה לבד ומבקש/ת הפסקה לפני שזה מתפוצץ, לפחות 3 פעמים בשבוע, תוך חודש", "steps": ["מסכמים יחד תוכנית ויסות: מה מרגיש שזה מתחיל, מה עוזר, למי לפנות", "כשהילד/ה יוצא/ת להפסקה ← מכבדים, נותנים זמן ובודקים אחר כך"], "principles": "אחריות משותפת: הילד/ה מוביל/ה, המבוגר מגבה", "sentences": ["ראיתי שלקחת הפסקה בזמן, כל הכבוד", "מה עבד לך הפעם?"], "seen": "מכיר/ה את הכלים אך מתבייש/ת להשתמש בהם מול אחרים", "needs": "כלים שמתאימים לגיל ולא מביכים", "why": "בגיל הזה חשובה האוטונומיה; תוכנית ויסות אישית מחזקת מסוגלות", "why_staff": "כשהילד/ה מנהל/ת את הרגיעה בעצמו/בעצמה, זה מחזיק גם כשאנחנו לא שם", "method": "ARC – ויסות ומסוגלות: תוכנית ויסות אישית"}}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, draft = true where public.mercury_library.content is null;
insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'goal', 'התמודדות עם תסכול', 'להמשיך או לבקש עזרה כשמשהו לא מצליח, בלי לוותר או להתפרץ', array['ויסות רגשי', 'למידה ותפקוד']::text[], 'ויסות רגשי', array['ARC', 'TF-CBT']::text[], '{"bank": 1, "review": 3, "scale": ["מתפרץ/ת או זורק/ת מיד", "עוזב/ת את המשימה בכעס", "ממשיך/ה עם עידוד צמוד", "מבקש/ת עזרה במקום לוותר", "מנסה דרך אחרת בעצמו/בעצמה"], "avoid": "לא לעשות במקום הילד/ה מיד; לא ללעוג לניסיון", "strengths": ["התמדה", "סבלנות"], "skills": ["בקשת עזרה"], "ages": {"2-5": {"targets": "ממשיך/ה לנסות עוד פעם אחת עם עידוד כשמשהו לא מצליח (מגדל, פאזל), ב-3 מתוך 5 פעמים", "steps": ["כשהמגדל נופל והילד/ה צורח/ת ← משקפים: זה מתסכל! ומציעים לבנות יחד", "כשמנסה שוב ← מתלהבים מהניסיון, לא רק מההצלחה"], "principles": "משבחים את המאמץ", "sentences": ["זה קשה! ננסה יחד?", "ראיתי שניסית שוב"], "seen": "זורק/ת חפצים או בוכה כשמשהו לא מצליח", "needs": "מבוגר שמחזיק את התסכול ומחלק את המשימה", "why": "חוויות של הצלחה אחרי קושי בונות תחושת מסוגלות", "why_staff": "כשעוזרים לנסות שוב, הילד/ה לומד/ת שקושי הוא לא סוף העולם", "method": "ARC – מסוגלות: חוויות הצלחה"}, "5-8": {"targets": "מבקש/ת עזרה או לוקח/ת הפסקה קצרה כשמשהו לא מצליח (במקום לזרוק או לוותר), ב-3 מתוך 5 פעמים בשבוע", "steps": ["לפני משימה קשה ← מחלקים אותה לצעדים קטנים ומסמנים כל צעד", "כשמתחיל תסכול ← מציעים: הפסקה, עזרה, או דרך אחרת"], "principles": "שלוש אפשרויות במקום פיצוץ", "sentences": ["רוצה הפסקה, עזרה או לנסות דרך אחרת?", "טעויות הן חלק מללמוד"], "seen": "מוותר/ת מהר, אומר/ת אני לא יודע/ת כלום", "needs": "משימות בגודל מתאים ודרכי יציאה מותרות", "why": "סבילות לתסכול נבנית כשהמשימה מעט מעל היכולת, עם תמיכה", "why_staff": "כשיש לילד/ה מה לעשות עם התסכול, פחות זורקים דברים", "method": "TF-CBT: התמודדות קוגניטיבית"}, "8-12": {"targets": "מזהה מחשבה מתסכלת (אני גרוע/ה) ומחליף/ה אותה במשפט מעודד, לפחות פעמיים בשבוע, תוך 3 חודשים", "steps": ["כשהילד/ה אומר/ת אני גרוע/ה בזה ← שואלים: מה היית אומר/ת לחבר שאומר את זה?", "בונים יחד רשימה של משפטים מעודדים ותולים במקום פרטי"], "principles": "המחשבה משפיעה על הרגש; אפשר לבחור משפט אחר", "sentences": ["עוד לא הצלחת, זה לא אומר שלא תצליח/י", "מה עזר לך פעם קודמת כשהיה קשה?"], "seen": "ביקורת עצמית קשה, נטישה של משימות ופעילויות", "needs": "קול פנימי מעודד במקום קול מבקר", "why": "ארגון מחדש של מחשבות אוטומטיות מפחית הימנעות ומחזק התמדה", "why_staff": "המשפט שהילד/ה אומר/ת לעצמו/לעצמה משנה אם ימשיך/תמשיך לנסות", "method": "TF-CBT: עיבוד קוגניטיבי"}}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, draft = true where public.mercury_library.content is null;
insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'goal', 'הקשבה לאותות הגוף', 'להרגיש מה קורה בגוף לפני שהרגש מתפרץ', array['ויסות רגשי', 'התנהגות מסכנת וגבולות']::text[], 'ויסות רגשי', array['ויסות חושי', 'NMT', 'ARC']::text[], '{"bank": 1, "review": 3, "scale": ["לא מרגיש/ה סימנים בכלל", "מזהה בדיעבד עם מבוגר", "מצביע/ה על מקום בגוף כשנשאל/ת", "מזהה סימן ואומר/ת", "מזהה סימן ופועל/ת להרגעה"], "avoid": "לא לומר זה לא כואב או זה כלום על תחושה שהילד/ה מתאר/ת", "strengths": ["הקשבה", "שליטה עצמית"], "skills": ["הירגעות בעזרת כלי"], "ages": {"2-5": {"targets": "מראה איפה בגוף זה מרגיש (בטן, ראש, ידיים) כשמבוגר שואל, ב-3 מתוך 5 פעמים", "steps": ["כשהילד/ה כועס/ת ← שמים יד על הלב שלנו ואומרים: הלב שלי דופק מהר כשאני כועס", "במשחק ← משחקים בגוף: לב מהיר אחרי ריצה, לב איטי במנוחה"], "principles": "משחק בגוף בזמן רגוע", "sentences": ["איפה בגוף זה מרגיש?", "הידיים שלך חזקות עכשיו"], "seen": "לא מזהה רעב, עייפות או כאב, ומתפרץ/ת בפתאומיות", "needs": "מבוגר שמתווך תחושות גופניות", "why": "פיתוח אינטרוספציה (תחושת הגוף מבפנים) הוא בסיס לוויסות", "why_staff": "כשהילד/ה מרגיש/ה את הגוף, אפשר לעזור לפני שזה מתפוצץ", "method": "ויסות חושי: מודעות גופנית"}, "5-8": {"targets": "אומר/ת סימן גוף מוקדם (בטן מתהפכת, ידיים חמות) לפני התפרצות, לפחות פעמיים בשבוע", "steps": ["מציירים יחד את מפת הגוף ← צובעים איפה מרגישים כעס, פחד, שמחה", "כשמבחינים בסימן ← שואלים: מה הגוף אומר לך עכשיו?"], "principles": "הגוף נותן אזהרה; לומדים לשמוע אותה", "sentences": ["הגוף שלך שולח לך הודעה. מה הוא אומר?", "שמתי לב שהאגרופים נסגרים"], "seen": "מתפרץ/ת בלי אזהרה נראית", "needs": "שפה לתחושות גוף", "why": "זיהוי סימנים מוקדמים מאפשר התערבות בחלון הסבילות", "why_staff": "אם הילד/ה מזהה את הסימן הראשון, יש זמן לעצור", "method": "ARC – ויסות: מודעות לעוררות"}, "8-12": {"targets": "מזהה לבד סימן גוף מוקדם ובוחר/ת פעולה מרגיעה, לפחות 3 פעמים בשבוע, תוך 3 חודשים", "steps": ["בונים יחד סולם עוררות 1–5 ← לכל מדרגה סימן גוף ופעולה", "פעם ביום ← בדיקה קצרה: איפה את/ה בסולם עכשיו?"], "principles": "מדידה עצמית יומית קצרה, בלי שיפוט", "sentences": ["איפה את/ה בסולם עכשיו?", "מה עושים במדרגה 3?"], "seen": "מבין/ה את הרעיון, אך מזהה מאוחר מדי", "needs": "תרגול יומי קצר ומעקב משותף", "why": "מעקב עוררות עצמי מחזק תפקודים ניהוליים ושליטה עצמית", "why_staff": "בדיקה קצרה ביום מלמדת את הילד/ה להכיר את עצמו/עצמה", "method": "NMT: ויסות מלמטה למעלה"}}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, draft = true where public.mercury_library.content is null;
insert into public.mercury_library (scope, kind, title, description, themes, category, content, draft) values ('mercury', 'avoid', 'ממה להימנע – ויסות', 'לא לנהל ויכוח בזמן התפרצות. לא לשלוח לפינה השקטה כעונש. לא לומר תירגע/י או אין סיבה.', array['ויסות רגשי']::text[], 'ויסות רגשי', '{"bank": 1, "ages": {"2-5": "לא להרים את הקול כשהילד/ה צועק/ת. לא להשאיר לבד בזמן התפרצות. לא לבקש להסביר בזמן בכי.", "5-8": "לא לנהל ויכוח בזמן התפרצות. לא לשלוח לפינה השקטה כעונש. לא לומר תירגע/י או אין סיבה.", "8-12": "לא להשפיל מול חברים. לא להתעקש על שיחה מיד אחרי פיצוץ. לא להגיב בציניות לרגש."}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, draft = true where public.mercury_library.content is null;
insert into public.mercury_library (scope, kind, title, description, themes, category, content, draft) values ('mercury', 'signs', 'אותות מוקדמים – ויסות', 'אגרופים קפוצים, קול שעולה, הליכה מהירה הלוך ושוב, עיניים מצומצמות.', array['ויסות רגשי']::text[], 'ויסות רגשי', '{"bank": 1, "ages": {"2-5": "פנים אדומות, בכי מתגבר, זריקת חפצים, שכיבה על הרצפה.", "5-8": "אגרופים קפוצים, קול שעולה, הליכה מהירה הלוך ושוב, עיניים מצומצמות.", "8-12": "שקט מתוח, תשובות קצרות ועוקצניות, טריקת דלת, התרחקות מהקבוצה."}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, draft = true where public.mercury_library.content is null;
insert into public.mercury_library (scope, kind, title, description, themes, category, content, draft) values ('mercury', 'calm', 'מה עוזר להירגע – ויסות', 'קופסת הרגעה, כדור לחיץ, נשימת בלון, לשתות מים, פינה שקטה. משפט: איזה כלי יעזור לך עכשיו?', array['ויסות רגשי']::text[], 'ויסות רגשי', '{"bank": 1, "ages": {"2-5": "חיבוק אם הילד/ה רוצה, נדנוד, שיר שקט, נשיפה על נוצה, שמיכה כבדה. משפט: אני כאן, נושמים יחד.", "5-8": "קופסת הרגעה, כדור לחיץ, נשימת בלון, לשתות מים, פינה שקטה. משפט: איזה כלי יעזור לך עכשיו?", "8-12": "הפסקה קצרה בטווח ראייה, מוזיקה באוזניות, הליכה עם מבוגר, ציור. משפט: קח/י את הזמן, אני פה כשתרצה/תרצי."}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, draft = true where public.mercury_library.content is null;
insert into public.mercury_library (scope, kind, title, description, themes, category, content, draft) values ('mercury', 'routine', 'שגרה – ויסות', 'בדיקת מד רגשות בבוקר ובערב, הפסקת תנועה כל שעה, שעה שקטה אחר הצהריים.', array['ויסות רגשי']::text[], 'ויסות רגשי', '{"bank": 1, "ages": {"2-5": "תנועה בבוקר (ריקוד, קפיצות), שעת מנוחה קבועה, שיר קבוע לפני מעבר.", "5-8": "בדיקת מד רגשות בבוקר ובערב, הפסקת תנועה כל שעה, שעה שקטה אחר הצהריים.", "8-12": "בדיקה עצמית יומית בסולם, זמן פעילות גופנית, מקום שקט מוסכם להפסקות."}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, draft = true where public.mercury_library.content is null;
insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'plan', 'תכנית: ויסות רגשי', '[שם] מתקשה להירגע ברגעי קושי, ולפעמים זה יוצא בגוף. כרגע הכי חשוב לעזור ל[שם] לזהות את הרגש ולהשתמש בדרך הרגעה שבחר/ה. [מה כבר עוזר].', array['ויסות רגשי']::text[], 'ויסות רגשי', array['ARC', 'ויסות חושי']::text[], '{"bank": 1, "summary": "[שם] מתקשה להירגע ברגעי קושי, ולפעמים זה יוצא בגוף. כרגע הכי חשוב לעזור ל[שם] לזהות את הרגש ולהשתמש בדרך הרגעה שבחר/ה. [מה כבר עוזר].", "goal_titles": ["זיהוי ושיום רגשות", "שימוש בכלי הרגעה", "פנייה למבוגר בטוח"], "parts": {"avoid": "ממה להימנע – ויסות", "signs": "אותות מוקדמים – ויסות", "calm": "מה עוזר להירגע – ויסות", "routine": "שגרה – ויסות"}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, draft = true where public.mercury_library.content is null;
insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'goal', 'קבלת נחמה וקרבה', 'לאפשר למבוגר לנחם, לטפל ולהיות קרוב', array['היקשרות וקשר עם מבוגר', 'ביטחון ויציבות']::text[], 'היקשרות וקשר עם מבוגר', array['Theraplay', 'DDP/PACE', 'ARC']::text[], '{"bank": 1, "review": 3, "scale": ["דוחה כל קרבה או נצמד/ת לכל זר", "מקבל/ת קרבה רק במשחק", "מקבל/ת נחמה ממבוגר מוכר אחד", "פונה לנחמה ומקבל/ת אותה", "מבקש/ת ומקבל/ת נחמה בצורה מותאמת"], "avoid": "לא לכפות חיבוק; מציעים ומחכים לתשובה", "strengths": ["קבלה", "חברות"], "skills": ["בקשת עזרה"], "ages": {"2-5": {"targets": "מאפשר/ת למבוגר מוכר להרים, לחבק או לנדנד כשבוכה, ב-3 מתוך 5 פעמים", "steps": ["כשהילד/ה בוכה ← מתקרבים, מציעים ידיים ומחכים לתנועה של הילד/ה", "פעמיים ביום ← משחק טיפוח קצר: קרם על הידיים, נשיפה על הלחי, ספירת אצבעות"], "principles": "טיפוח שובב ונעים, בלי דרישות", "sentences": ["רוצה לבוא אליי?", "פה שומרים עליך"], "seen": "לא מחפש/ת נחמה, או הולך/ת לכל מבוגר בלי הבחנה", "needs": "מבוגרים קבועים שמטפלים בחום ובעקביות", "why": "היקשרות נבנית דרך טיפוח גופני חוזר; הבחנה בין מבוגרים מוכרים לזרים היא סימן להיקשרות מתפתחת", "why_staff": "כל חיבוק שהילד/ה מקבל/ת בנוח בונה אמון במבוגרים", "method": "Theraplay: טיפוח"}, "5-8": {"targets": "מקבל/ת עזרה או נחמה ממבוגר (ולא דוחף/ת או בורח/ת), ב-3 מתוך 5 פעמים בשבוע", "steps": ["כשהילד/ה נפגע/ת ודוחה ← נשארים קרוב, מדברים ברכות: אני פה כשתרצה/תרצי", "בזמן רגוע ← משחקי Theraplay קצרים: מראה, ידיים בידיים, הנחת כרית"], "principles": "נשארים זמינים גם כשנדחים", "sentences": ["אני פה, לא הולכים לשום מקום", "אפשר לבחור אם לבוא"], "seen": "אומר/ת לא צריך/ה אף אחד, אבל נשבר/ת לבד", "needs": "מבוגר שלא מוותר ולא נעלב מהדחייה", "why": "דחיית קרבה היא אסטרטגיה הגנתית; עמידות המבוגר מאפשרת חוויה מתקנת", "why_staff": "כשהילד/ה דוחה אותנו, זה לא אישי. נשארים בסביבה", "method": "DDP/PACE: קבלה ואמפתיה"}, "8-12": {"targets": "מספר/ת למבוגר קבוע על משהו שהטריד אותו/אותה, לפחות פעם בשבוע, תוך 3 חודשים", "steps": ["קובעים זמן קבוע של 10 דקות ביום עם מבוגר אחד ← מה שהילד/ה בוחר/ת לעשות", "כשהילד/ה משתף/ת ← מקשיבים, משקפים, ולא ממהרים לפתרונות"], "principles": "זמן קבוע, מבוגר קבוע, הקשבה בלי שיפוט", "sentences": ["מעניין אותי מה עובר עליך", "תודה ששיתפת אותי"], "seen": "שומר/ת הכל בפנים, נראה/ית בסדר אך מתפרץ/ת פתאום", "needs": "קשר יציב עם מבוגר אחד לפחות", "why": "בגיל הזה הקשר נבנה בשיחה ובשותפות; זמן קבוע מאפשר חשיפה הדרגתית", "why_staff": "10 דקות קבועות ביום עושות הבדל גדול באמון", "method": "ARC – התקשרות: זמן מיוחד עם מבוגר"}}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, draft = true where public.mercury_library.content is null;
insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'goal', 'תיקון קשר אחרי משבר', 'לחזור לקשר עם המבוגר אחרי ריב, גבול או התפרצות', array['היקשרות וקשר עם מבוגר', 'התנהגות מסכנת וגבולות']::text[], 'היקשרות וקשר עם מבוגר', array['DDP/PACE', 'ARC']::text[], '{"bank": 1, "review": 3, "scale": ["נשאר/ת בכעס ימים", "חוזר/ת רק כשמבוגר יוזם ומתעקש", "חוזר/ת אחרי יוזמה של מבוגר", "מקבל/ת תיקון בקלות", "יוזם/ת תיקון בעצמו/בעצמה"], "avoid": "לא להעניש בשתיקה או בהתרחקות; המבוגר יוזם את התיקון", "strengths": ["כנות", "אחריות"], "skills": ["פתרון בעיה במילים"], "ages": {"2-5": {"targets": "חוזר/ת למשחק או לחיבוק עם המבוגר תוך שעה אחרי גבול, ב-3 מתוך 5 פעמים", "steps": ["אחרי שהצבנו גבול ← חוזרים אחרי כמה דקות עם חיוך ומשחק קטן", "אומרים במילה: את/ה חשוב/ה לי"], "principles": "הגבול על ההתנהגות, הקשר נשאר", "sentences": ["כעסת עליי, ואני עדיין פה", "בוא/י נשחק"], "seen": "מתרחק/ת אחרי שאומרים לו/לה לא", "needs": "לחוות שהקשר לא נשבר בגלל גבול", "why": "חוויות של קרע ותיקון (rupture and repair) הן הבסיס להיקשרות בטוחה", "why_staff": "אחרי כל לא, חוזרים לקשר. זה מלמד שהקשר חזק", "method": "DDP/PACE: חיבור מחדש אחרי גבול"}, "5-8": {"targets": "מקבל/ת את פניית המבוגר לתיקון אחרי משבר (מילה, משחק, יד) באותו יום, ב-3 מתוך 4 פעמים", "steps": ["אחרי שהילד/ה נרגע/ת ← ניגשים: היה לנו קשה קודם, אני רוצה שנהיה בסדר", "מציעים משהו קטן ביחד (ציור, כדור) בלי לדבר שוב על מה שהיה"], "principles": "המבוגר אחראי לתיקון, לא הילד/ה", "sentences": ["היה לנו רגע קשה. אני עדיין איתך", "סליחה שצעקתי"], "seen": "בטוח/ה שהמבוגר שונא אותו/אותה אחרי ריב", "needs": "מבוגר שחוזר ומתקן", "why": "תיקון שמוביל מבוגר מפריך את האמונה שקשר נהרס בגלל קונפליקט", "why_staff": "כשאנחנו מתקנים, הילד/ה לומד/ת שאפשר לריב ולהישאר קרובים", "method": "ARC – התקשרות: תיקון"}, "8-12": {"targets": "משתתף/ת בשיחת תיקון קצרה (מה קרה, מה הרגשנו, מה עכשיו) אחרי משבר, ב-3 מתוך 4 פעמים", "steps": ["אחרי שנרגעים ← שיחה קצרה בסקרנות: מה קרה לך שם?", "המבוגר לוקח אחריות על החלק שלו ומזמין את הילד/ה לחלק שלו/שלה"], "principles": "סקרנות במקום האשמה", "sentences": ["מה קרה לך שם, לפני שזה התפוצץ?", "גם אני יכולתי להגיב אחרת"], "seen": "מתבייש/ת אחרי התפרצות ונמנע/ת ממבוגרים", "needs": "לראות שאפשר לדבר על משבר בלי בושה", "why": "שיחת תיקון מפחיתה בושה ומחזקת יכולת רפלקטיבית", "why_staff": "שיחה קצרה ורגועה אחרי פיצוץ מונעת את הפיצוץ הבא", "method": "DDP/PACE: סקרנות ואמפתיה"}}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, draft = true where public.mercury_library.content is null;
insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'goal', 'משחק משותף עם מבוגר', 'ליהנות ממשחק עם מבוגר, לשתף פעולה ולצחוק יחד', array['היקשרות וקשר עם מבוגר', 'קשרים חברתיים']::text[], 'היקשרות וקשר עם מבוגר', array['Theraplay', 'NMT']::text[], '{"bank": 1, "review": 3, "scale": ["לא משחק/ת עם מבוגר בכלל", "משחק/ת רגע קצר ועוזב/ת", "משחק/ת 5 דקות כשמבוגר מוביל", "משחק/ת ונהנה/ית ומקבל/ת הובלה", "יוזם/ת משחק ומשתף/ת פעולה"], "avoid": "לא להפוך את המשחק לתחרות או ללמידה; המטרה היא הנאה יחד", "strengths": ["שיתוף", "יצירתיות"], "skills": ["המתנה לתור"], "ages": {"2-5": {"targets": "משתתף/ת במשחק מבוגר-ילד קצר (קוקו, ידיים, בועות) 5 דקות, פעם ביום, ב-5 מתוך 7 ימים", "steps": ["פעם ביום ← משחק קצר וקבוע: בועות, קוקו, פעמונים", "כשהילד/ה צוחק/ת ← חוזרים על אותו משחק עוד פעם"], "principles": "קצר, צפוי, מצחיק", "sentences": ["איפה הידיים שלך? מצאתי!", "עוד פעם?"], "seen": "משחק/ת לבד, לא מסתכל/ת על המבוגר", "needs": "חוויות חוזרות של הנאה משותפת", "why": "משחק דיאדי ומשמח מפעיל מערכות קשר ומגביר ויסות", "why_staff": "5 דקות של צחוק יחד בונות קשר יותר משיחה ארוכה", "method": "Theraplay: מעורבות ושמחה"}, "5-8": {"targets": "משחק/ת עם מבוגר משחק עם כללים פשוטים 10 דקות ומקבל/ת את התור, ב-4 מתוך 7 ימים", "steps": ["בוחרים משחק אהוב ← משחקים בזמן קבוע עם אותו מבוגר", "כשהילד/ה מתקשה לחכות ← מקצרים את התור ומשבחים כל המתנה"], "principles": "המבוגר מבנה, הילד/ה מצליח/ה", "sentences": ["עכשיו התור שלך, אחר כך שלי", "איזה כיף לשחק איתך"], "seen": "רוצה לשלוט במשחק, עוזב/ת כשמפסיד/ה", "needs": "משחק עם מבוגר קשוב שמאפשר הצלחה", "why": "משחק מובנה עם מבוגר מתרגל ויסות, תור ושיתוף בתוך קשר", "why_staff": "משחק קבוע עם מבוגר מלמד לשחק גם עם ילדים", "method": "Theraplay: מבנה ומעורבות"}, "8-12": {"targets": "משתתף/ת בפעילות משותפת עם מבוגר (בישול, ספורט, משחק קופסה) לפחות פעמיים בשבוע", "steps": ["מתכננים יחד פעילות שבועית ← הילד/ה בוחר/ת מתוך אפשרויות", "בזמן הפעילות ← מתמקדים בהנאה ובשיחה קלה, לא בתיקונים"], "principles": "פעילות יחד היא הזדמנות לקשר בלי לחץ של שיחה", "sentences": ["מה בא לך לעשות השבוע?", "נהניתי לעשות את זה איתך"], "seen": "מתרחק/ת ממבוגרים, מעדיף/ה מסכים", "needs": "קשר דרך עשייה משותפת", "why": "בגיל הזה עשייה משותפת מאפשרת קרבה בלי מבט ישיר ודרישה לשיתוף רגשי", "why_staff": "לפעמים הכי קל לדבר תוך כדי שעושים משהו יחד", "method": "NMT: פעילות מווסתת ומתגמלת"}}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, draft = true where public.mercury_library.content is null;
insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'goal', 'שיתוף בחוויות ורגשות', 'לספר למבוגר על מה שקרה ועל מה שמרגישים', array['היקשרות וקשר עם מבוגר', 'ויסות רגשי']::text[], 'היקשרות וקשר עם מבוגר', array['DDP/PACE', 'TF-CBT', 'ARC']::text[], '{"bank": 1, "review": 3, "scale": ["לא משתף/ת בכלל", "משתף/ת רק כשנשאל/ת ובמילה", "מספר/ת על אירועים, לא על רגשות", "מספר/ת גם על רגשות", "יוזם/ת שיתוף כשצריך/ה"], "avoid": "לא לחקור ולא לבקש פרטים על אירועים טראומטיים; זה תפקיד המטפל/ת", "strengths": ["כנות", "אומץ"], "skills": ["מציאת מילים ברגע של קושי"], "ages": {"2-5": {"targets": "מראה או מספר/ת במילה, בציור או בבובה מה קרה לו/לה היום, ב-3 מתוך 5 ימים", "steps": ["בסוף היום ← יושבים יחד עם בובה ושואלים: מה הבובה עשתה היום?", "כשהילד/ה מראה משהו ← משקפים בפשטות ולא מוסיפים שאלות"], "principles": "שיתוף דרך משחק", "sentences": ["ספר/י לי על הציור", "זה היה כיף או קשה?"], "seen": "לא מספר/ת, או חוזר/ת על משחק אחד שוב ושוב", "needs": "דרכים לא מילוליות לשתף", "why": "משחק הוא שפת העיבוד של ילדים צעירים", "why_staff": "דרך בובה או ציור ילדים קטנים מספרים מה שקשה להם להגיד", "method": "ARC – התקשרות: היענות לאותות"}, "5-8": {"targets": "מספר/ת למבוגר על דבר אחד טוב ואחד קשה מהיום, ב-4 מתוך 7 ימים", "steps": ["טקס ערב קבוע ← שאלה אחת על משהו טוב ושאלה אחת על משהו קשה", "כשמשתף/ת משהו מדאיג ← מקשיבים, מרגיעים, ומעבירים למטפל/ת"], "principles": "טקס קבוע ושאלות פשוטות", "sentences": ["מה היה הדבר הכי טוב היום?", "היה משהו קשה?"], "seen": "עונה תמיד היה בסדר", "needs": "מבוגר שמקשיב בכל יום באותה דרך", "why": "שיתוף יומי מובנה מחזק נרטיב ותחושת היות מוחזק/ת", "why_staff": "שתי שאלות קבועות בערב פותחות דלת לשיחה", "method": "TF-CBT: הבעה רגשית"}, "8-12": {"targets": "משתף/ת מבוגר קבוע ברגש או בדאגה לפחות פעם בשבוע, ביוזמתו/ביוזמתה, תוך 3 חודשים", "steps": ["כשהילד/ה מתחיל/ה לספר ← עוצרים מה שעושים ומקשיבים", "מסכמים בעדינות ובודקים: מה היית רוצה שיקרה עכשיו?"], "principles": "הקשבה מלאה; לא מבטיחים סודיות, מבטיחים אכפתיות", "sentences": ["טוב שסיפרת לי", "את/ה לא לבד עם זה"], "seen": "משתף/ת רק בעקיפין, בבדיחות או בהתנהגות", "needs": "מבוגר שאפשר לסמוך שיקשיב ולא יבהל", "why": "חשיפה רגשית ביוזמת הילד/ה היא סמן להיקשרות בטוחה מתפתחת", "why_staff": "כשהילד/ה בוחר/ת לספר לנו, מקשיבים עד הסוף", "method": "DDP/PACE: קבלה ואמפתיה"}}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, draft = true where public.mercury_library.content is null;
insert into public.mercury_library (scope, kind, title, description, themes, category, content, draft) values ('mercury', 'avoid', 'ממה להימנע – היקשרות', 'לא להתרחק כעונש. לא לנזוף מול אחרים. לא להבטיח הבטחות שקשה לקיים.', array['היקשרות וקשר עם מבוגר']::text[], 'היקשרות וקשר עם מבוגר', '{"bank": 1, "ages": {"2-5": "לא לכפות חיבוק או מגע. לא להחליף מבוגרים לעתים קרובות בטיפול היומי. לא להיעלם בלי להיפרד.", "5-8": "לא להתרחק כעונש. לא לנזוף מול אחרים. לא להבטיח הבטחות שקשה לקיים.", "8-12": "לא להשתמש בקשר כאיום (אם לא... לא אבוא). לא להעביר הלאה מה שסיפר/ה בלי לומר לו/לה. לא לצחוק על רגשות."}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, draft = true where public.mercury_library.content is null;
insert into public.mercury_library (scope, kind, title, description, themes, category, content, draft) values ('mercury', 'signs', 'אותות מוקדמים – היקשרות', 'בודק/ת את המבוגר בהתגרות, אומר/ת אתה לא אוהב אותי, דוחה ומתקרב/ת לסירוגין.', array['היקשרות וקשר עם מבוגר']::text[], 'היקשרות וקשר עם מבוגר', '{"bank": 1, "ages": {"2-5": "נצמד/ת חזק או מתרחק/ת, בוכה כשמבוגר יוצא, הולך/ת לכל זר.", "5-8": "בודק/ת את המבוגר בהתגרות, אומר/ת אתה לא אוהב אותי, דוחה ומתקרב/ת לסירוגין.", "8-12": "מבחן אמון: שוברים כלל ומחכים לתגובה, אדישות מופגנת, ציניות."}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, draft = true where public.mercury_library.content is null;
insert into public.mercury_library (scope, kind, title, description, themes, category, content, draft) values ('mercury', 'calm', 'מה עוזר להירגע – היקשרות', 'ישיבה ליד המבוגר, משחק קצר יחד, מגע ביד אם מתאים. משפט: אני פה איתך, נהיה בסדר.', array['היקשרות וקשר עם מבוגר']::text[], 'היקשרות וקשר עם מבוגר', '{"bank": 1, "ages": {"2-5": "המבוגר המוכר, חפץ מעבר, נדנוד ושיר קבוע. משפט: אני פה, שומרים עליך.", "5-8": "ישיבה ליד המבוגר, משחק קצר יחד, מגע ביד אם מתאים. משפט: אני פה איתך, נהיה בסדר.", "8-12": "שיחה קצרה עם המבוגר הקבוע, הליכה יחד, הודעה שהקשר נשאר. משפט: מה שקרה לא משנה את הקשר שלנו."}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, draft = true where public.mercury_library.content is null;
insert into public.mercury_library (scope, kind, title, description, themes, category, content, draft) values ('mercury', 'routine', 'שגרה – היקשרות', 'זמן מיוחד יומי של 10 דקות. הודעה על מי מגיע במשמרת הבאה. טקס פרידה ומפגש קבוע.', array['היקשרות וקשר עם מבוגר']::text[], 'היקשרות וקשר עם מבוגר', '{"bank": 1, "ages": {"2-5": "מבוגר קבוע לטקס השינה ולארוחות כשאפשר. פרידה קבועה בסוף משמרת. משחק טיפוח קצר פעמיים ביום.", "5-8": "זמן מיוחד יומי של 10 דקות. הודעה על מי מגיע במשמרת הבאה. טקס פרידה ומפגש קבוע.", "8-12": "שיחת ערב קבועה עם מבוגר. פעילות שבועית משותפת. מבוגר קבוע שמעודכן בכל מה שחשוב."}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, draft = true where public.mercury_library.content is null;
insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'plan', 'תכנית: היקשרות וקשר עם מבוגר', '[שם] מתקשה לסמוך על מבוגרים ולקבל מהם עזרה. כרגע הכי חשוב לבנות קשר יציב עם [מבוגר קבוע], דרך משחק, נחמה ותיקון אחרי משברים. [מה כבר עוזר].', array['היקשרות וקשר עם מבוגר']::text[], 'היקשרות וקשר עם מבוגר', array['DDP/PACE', 'Theraplay']::text[], '{"bank": 1, "summary": "[שם] מתקשה לסמוך על מבוגרים ולקבל מהם עזרה. כרגע הכי חשוב לבנות קשר יציב עם [מבוגר קבוע], דרך משחק, נחמה ותיקון אחרי משברים. [מה כבר עוזר].", "goal_titles": ["קבלת נחמה וקרבה", "תיקון קשר אחרי משבר", "זיהוי ושיום רגשות"], "parts": {"avoid": "ממה להימנע – היקשרות", "signs": "אותות מוקדמים – היקשרות", "calm": "מה עוזר להירגע – היקשרות", "routine": "שגרה – היקשרות"}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, draft = true where public.mercury_library.content is null;
insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'goal', 'זיהוי חוזקות אישיות', 'לזהות דברים טובים בעצמי ולהגיד אותם', array['זהות ודימוי עצמי']::text[], 'זהות ודימוי עצמי', array['ARC', 'TF-CBT']::text[], '{"bank": 1, "review": 3, "scale": ["אומר/ת רק דברים רעים על עצמו/עצמה", "מקבל/ת מחמאה בלי לדחות", "מסכים/ה עם חוזקה שמבוגר אומר", "אומר/ת חוזקה אחת בעצמו/בעצמה", "מתאר/ת כמה חוזקות ודוגמה לכל אחת"], "avoid": "לא להשוות לילדים אחרים; לא לשבח באופן כללי וריק, אלא במעשה מסוים", "strengths": ["אומץ", "יצירתיות"], "skills": [], "ages": {"2-5": {"targets": "מחייך/ת או מסכים/ה כשמבוגר אומר משהו טוב ומסוים על מה שעשה/תה, ב-4 מתוך 5 פעמים", "steps": ["כשהילד/ה עושה משהו טוב ← אומרים בדיוק מה: עזרת לחבר לקום", "בערב ← מספרים לילד/ה סיפור קצר על משהו טוב שעשה/תה היום"], "principles": "שבח מדויק על מעשה, לא על מי שהילד/ה", "sentences": ["ראיתי שחיכית לתור", "עזרת לחבר, זה היה נדיב"], "seen": "לא מגיב/ה למחמאות או מתנהג/ת רע מיד אחריהן", "needs": "לשמוע שוב ושוב שיש בו/בה טוב", "why": "דימוי עצמי נבנה מהשתקפות במבט של מבוגר משמעותי", "why_staff": "כשאומרים לילד/ה מה בדיוק עשה/תה טוב, הוא/היא מתחיל/ה להאמין שזה נכון", "method": "ARC – מסוגלות: זהות חיובית"}, "5-8": {"targets": "אומר/ת חוזקה אחת שלו/שלה כשמבוגר שואל, ב-3 מתוך 5 ימים", "steps": ["כשמניחים לבנה במקדש ← אומרים בקול את החוזקה ושואלים: מתי עוד ראית את זה אצלך?", "יוצרים יחד מחברת חוזקות ← מוסיפים ציור או מילה פעם בשבוע"], "principles": "מחברים בין חוזקה למעשה שהילד/ה זוכר/ת", "sentences": ["איזה כוח השתמשת בו היום?", "גם אתמול ראיתי את הסבלנות שלך"], "seen": "אומר/ת אני רע/ה, אני טיפש/ה", "needs": "ראיות מוחשיות לחוזקות", "why": "עדות חיצונית מתועדת מסייעת לבנות נרטיב עצמי חלופי", "why_staff": "כשיש לילד/ה דוגמאות, קשה לו/לה להגיד שאין בו/בה כלום טוב", "method": "ARC – מסוגלות: זיהוי חוזקות"}, "8-12": {"targets": "מתאר/ת לפחות 3 חוזקות ודוגמה לכל אחת, ויודע/ת להזכיר לעצמו/לעצמה אותן ברגע קשה, תוך 3 חודשים", "steps": ["כשהילד/ה מבקר/ת את עצמו/עצמה ← לא מתווכחים; שואלים: מה היה אומר מישהו שמכיר אותך טוב?", "פעם בשבוע ← בוחרים יחד חוזקה ומחפשים אותה בשבוע"], "principles": "לא משכנעים; עוזרים לגלות", "sentences": ["מה היה אומר עליך מישהו שמכיר אותך?", "איזה כוח שלך עזר לך השבוע?"], "seen": "דימוי עצמי שלילי עמוק, דוחה מחמאות", "needs": "לגלות בעצמו/בעצמה ולא רק לשמוע", "why": "אמונות ליבה שליליות מתוקנות טוב יותר בגילוי עצמי מונחה מאשר בשכנוע", "why_staff": "עדיף לשאול שאלה שתעזור לגלות חוזקה, מאשר להתווכח עם הילד/ה", "method": "TF-CBT: עיבוד קוגניטיבי של אמונות על עצמי"}}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, draft = true where public.mercury_library.content is null;
insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'goal', 'התמודדות עם טעויות', 'לטעות בלי להרגיש שאני כולו/כולה רע/ה', array['זהות ודימוי עצמי', 'ויסות רגשי', 'למידה ותפקוד']::text[], 'זהות ודימוי עצמי', array['ARC', 'TF-CBT', 'DDP/PACE']::text[], '{"bank": 1, "review": 3, "scale": ["טעות מובילה להתפרקות או להתפרצות", "מסתיר/ה טעויות", "מודה בטעות עם תמיכה", "מתקן/ת עם עזרה", "מודה, מתקן/ת וממשיך/ה"], "avoid": "לא להעיר על טעות מול כולם; לא לומר שוב פעם עשית את זה", "strengths": ["כנות", "אחריות"], "skills": ["פתרון בעיה במילים"], "ages": {"2-5": {"targets": "ממשיך/ה לשחק אחרי ששפך/ה או שבר/ה משהו, עם עזרה בתיקון, ב-3 מתוך 5 פעמים", "steps": ["כשמשהו נשפך ← אומרים ברגיעה: אופס, קורה. מנקים יחד", "כשהילד/ה נבהל/ת מטעות ← מחבקים ומראים שהכל בסדר"], "principles": "טעות היא אירוע קטן, לא אסון", "sentences": ["אופס, קורה. ננקה יחד", "זה בסדר, כולם טועים"], "seen": "נבהל/ת מאוד מטעות, מסתתר/ת או בוכה", "needs": "תגובה רגועה של מבוגר לטעויות", "why": "תגובות מבוגר לטעות מעצבות את היחס הפנימי של הילד/ה לעצמו/לעצמה", "why_staff": "כשאנחנו רגועים מול טעות, הילד/ה לומד/ת שהוא/היא לא בצרות", "method": "ARC – התקשרות: תגובה מכווננת"}, "5-8": {"targets": "מודה בטעות ועוזר/ת לתקן (בלי להאשים אחרים או להתפרץ), ב-3 מתוך 5 פעמים בשבוע", "steps": ["כשהילד/ה מכחיש/ה ← לא נלחמים על האמת; אומרים: בוא/י נבדוק איך מתקנים", "כשמודה ← מודים לו/לה על הכנות לפני כל דבר אחר"], "principles": "הכנות מקבלת תודה, התיקון בא אחריה", "sentences": ["תודה שאמרת את האמת", "איך אפשר לתקן?"], "seen": "מאשים/ה אחרים, משקר/ת כדי להימנע מבושה", "needs": "להרגיש שאפשר לטעות בלי לאבד את המבוגר", "why": "שקר והאשמה הם לרוב הגנה מבושה; הפחתת בושה מאפשרת אחריות", "why_staff": "כשלא מבישים, קל לילד/ה להודות ולתקן", "method": "DDP/PACE: קבלה ללא בושה"}, "8-12": {"targets": "מתאר/ת טעות כמשהו שעשה/תה (ולא כמשהו שהוא/היא), ומציע/ה דרך לתקן, ב-3 מתוך 4 פעמים", "steps": ["כשהילד/ה אומר/ת אני גרוע/ה ← מפרידים: עשית משהו לא טוב, את/ה לא רע/ה", "שיחה קצרה ← מה למדת? מה תעשה/תעשי בפעם הבאה?"], "principles": "הפרדה בין מעשה לזהות", "sentences": ["עשית טעות, זה לא אומר שאת/ה רע/ה", "מה תעשה/תעשי אחרת בפעם הבאה?"], "seen": "מכליל/ה טעות אחת לכל העצמי", "needs": "שפה שמפרידה בין מעשה לבין מי שאני", "why": "הבחנה בין אשמה (על מעשה) לבושה (על העצמי) מחזקת אחריות ומפחיתה הרס עצמי", "why_staff": "ילד/ה שיודע/ת שהוא/היא לא רע/ה, יכול/ה לתקן את מה שעשה/תה", "method": "TF-CBT: עיבוד קוגניטיבי"}}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, draft = true where public.mercury_library.content is null;
insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'goal', 'סיפור החיים שלי', 'להכיר את הסיפור שלי, את המשפחה ואת מה שקרה, בקצב שמתאים לי', array['זהות ודימוי עצמי', 'אובדן ופרידה']::text[], 'זהות ודימוי עצמי', array['TF-CBT', 'DDP/PACE']::text[], '{"bank": 1, "review": 3, "scale": ["נמנע/ת מכל דבר שקשור לעבר", "מקשיב/ה לסיפור קצר עם מבוגר", "שואל/ת שאלות על הסיפור", "משתף/ת פרטים מהסיפור שלו/שלה", "מספר/ת את הסיפור בשלמות ובביטחון"], "avoid": "עבודה על סיפור החיים נעשית רק עם המטפל/ת; הצוות לא פותח את הנושא ביוזמתו", "strengths": ["אומץ", "כנות"], "skills": [], "ages": {"2-5": {"targets": "נהנה/ית מסיפור קצר בתמונות על עצמו/עצמה (מתי הגיע/ה, מי אוהב אותו/אותה) לפחות פעם בשבוע", "steps": ["כשהילד/ה מראה תמונה או מספר/ת משהו ← מקשיבים ומשקפים בחום", "מכינים עם המטפל/ת אלבום קטן עם תמונות מהמרכז"], "principles": "סיפור פשוט, חם ואמיתי", "sentences": ["זה את/ה כשהגעת לפה", "יש הרבה אנשים שאוהבים אותך"], "seen": "שואל/ת איפה אמא, למה אני פה", "needs": "סיפור פשוט ועקבי שכל המבוגרים אומרים", "why": "נרטיב קוהרנטי ועקבי מפחית בלבול ומספק עוגן זהותי", "why_staff": "חשוב שכל הצוות יענה באותן מילים פשוטות שנקבעו עם המטפל/ת", "method": "TF-CBT: נרטיב מותאם גיל"}, "5-8": {"targets": "שואל/ת שאלות על הסיפור שלו/שלה ומקבל/ת תשובות מוסכמות, ומשתתף/ת בספר החיים עם המטפל/ת", "steps": ["כשהילד/ה שואל/ת שאלה קשה ← עונים במשפט המוסכם ואומרים שאפשר לדבר על זה עם המטפל/ת", "מעבירים למטפל/ת את השאלה שהילד/ה שאל/ה"], "principles": "לא ממציאים תשובות; משתמשים במשפטים המוסכמים", "sentences": ["זו שאלה חשובה. בוא/י נשאל יחד את המטפל/ת", "זה לא קרה בגללך"], "seen": "מאשים/ה את עצמו/עצמה במה שקרה", "needs": "תשובות כנות ומותאמות, ושלא יאשים/תאשים את עצמו/עצמה", "why": "ילדים בגיל הזה נוטים לחשיבה אגוצנטרית ולהאשמה עצמית; נרטיב מתקן מפחית אשמה", "why_staff": "הכי חשוב לומר לילד/ה שזה לא באשמתו/באשמתה", "method": "TF-CBT: נרטיב טראומה"}, "8-12": {"targets": "משתתף/ת בעבודה על ספר החיים עם המטפל/ת ומרגיש/ה גאווה בחלקים מהזהות שלו/שלה, תוך 3 חודשים", "steps": ["כשהילד/ה רוצה לדבר על המשפחה ← מקשיבים בלי לשפוט את ההורים", "מעודדים לשתף את המטפל/ת ומזכירים את מועד המפגש"], "principles": "כבוד למשפחה ולשורשים, גם כשהיה קשה", "sentences": ["מותר לאהוב את המשפחה וגם לכעוס", "הסיפור שלך שייך לך"], "seen": "רגשות מעורבים כלפי המשפחה, חשש לבגוד בה", "needs": "מקום לרגשות מעורבים בלי שיפוט", "why": "שילוב העבר בזהות מאפשר המשכיות עצמית ומפחית פיצול", "why_staff": "אסור לדבר רע על ההורים. הילד/ה צריך/ה לדעת שמותר לו/לה לאהוב אותם", "method": "DDP/PACE: קבלת רגשות מעורבים"}}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, draft = true where public.mercury_library.content is null;
insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'goal', 'בחירה והבעת רצון', 'להגיד מה אני רוצה ולבחור, ולהרגיש שמקשיבים לי', array['זהות ודימוי עצמי', 'ביטחון ויציבות']::text[], 'זהות ודימוי עצמי', array['ARC', 'DDP/PACE']::text[], '{"bank": 1, "review": 1, "scale": ["לא מביע/ה רצון, מסכים/ה לכל דבר או מסרב/ת לכל דבר", "בוחר/ת מבין שתי אפשרויות עם עידוד", "בוחר/ת לבד מבין אפשרויות", "מבקש/ת דבר שרוצה במילים", "מביע/ה דעה ומנהל/ת משא ומתן בכבוד"], "avoid": "לא להציע בחירה כשאין באמת בחירה", "strengths": ["אומץ", "אחריות"], "skills": [], "ages": {"2-5": {"targets": "בוחר/ת מבין שתי אפשרויות (צבע, משחק, בגד) כשמציעים, לפחות 3 פעמים ביום", "steps": ["במהלך היום ← מציעים שתי אפשרויות קטנות: הכוס האדומה או הכחולה?", "כשהילד/ה בוחר/ת ← מכבדים מיד את הבחירה"], "principles": "הרבה בחירות קטנות ואמיתיות", "sentences": ["רוצה את זה או את זה?", "בחרת, איזה יופי"], "seen": "מסכים/ה לכל דבר, או מסרב/ת לכל הצעה", "needs": "חוויה שהקול שלו/שלה משנה משהו", "why": "בחירה מחזקת תחושת שליטה, שנפגעה בחוויות טראומטיות", "why_staff": "בחירות קטנות במשך היום נותנות לילד/ה תחושה שיש לו/לה קול", "method": "ARC – מסוגלות: בחירה"}, "5-8": {"targets": "מבקש/ת במילים משהו שרוצה (במקום לקחת או להתפרץ), ב-3 מתוך 5 פעמים בשבוע", "steps": ["כשהילד/ה לוקח/ת בלי לבקש ← עוצרים בעדינות ומזמינים: איך מבקשים?", "כשמבקש/ת ← נענים כשאפשר, ומסבירים כשאי אפשר"], "principles": "בקשה במילים מקבלת מענה", "sentences": ["אפשר לבקש ממני", "כשמבקשים, אני מקשיב/ה"], "seen": "לוקח/ת דברים בכוח, לא מאמין/ה שבקשה תיענה", "needs": "ניסיון שבקשה עובדת", "why": "היענות עקבית לבקשה מילולית מחזקת תקשורת על פני התנהגות", "why_staff": "כשבקשה במילים עובדת, הילד/ה לוקח/ת פחות בכוח", "method": "ARC – התקשרות: היענות"}, "8-12": {"targets": "מביע/ה דעה על דבר שנוגע לו/לה (תוכנית, פעילות, חדר) בדרך מכבדת, לפחות פעם בשבוע", "steps": ["כשמתכננים משהו שקשור לילד/ה ← שואלים לדעתו/לדעתה ומתחשבים בה", "כשאי אפשר להיענות ← מסבירים למה ומציעים פשרה"], "principles": "שותפות אמיתית בהחלטות", "sentences": ["מה דעתך?", "שמעתי אותך. הנה מה שאפשר"], "seen": "מרגיש/ה שאף אחד לא שואל אותו/אותה", "needs": "מקום אמיתי בהחלטות", "why": "השתתפות בהחלטות מחזקת סוכנות וזהות", "why_staff": "ילד/ה ששואלים לדעתו/לדעתה משתף/ת פעולה יותר", "method": "DDP/PACE: שיח מכבד"}}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, draft = true where public.mercury_library.content is null;
insert into public.mercury_library (scope, kind, title, description, themes, category, content, draft) values ('mercury', 'avoid', 'ממה להימנע – זהות', 'לא לומר אתה תמיד או את אף פעם. לא להעיר על טעות מול כולם. לא לדבר רע על ההורים.', array['זהות ודימוי עצמי']::text[], 'זהות ודימוי עצמי', '{"bank": 1, "ages": {"2-5": "לא לקרוא בשם גנאי, גם בצחוק. לא להשוות לילדים אחרים. לא לצחוק על טעויות.", "5-8": "לא לומר אתה תמיד או את אף פעם. לא להעיר על טעות מול כולם. לא לדבר רע על ההורים.", "8-12": "לא להשפיל מול חברים. לא לחשוף פרטים אישיים מול אחרים. לא לבטל דעה שהילד/ה מביע/ה."}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, draft = true where public.mercury_library.content is null;
insert into public.mercury_library (scope, kind, title, description, themes, category, content, draft) values ('mercury', 'signs', 'אותות מוקדמים – זהות', 'אומר/ת אני רע/ה, אני טיפש/ה, הורס/ת את מה שיצר/ה, מוותר/ת מראש.', array['זהות ודימוי עצמי']::text[], 'זהות ודימוי עצמי', '{"bank": 1, "ages": {"2-5": "מתחבא/ת אחרי טעות, מכה את עצמו/עצמה, לא מגיב/ה למחמאה.", "5-8": "אומר/ת אני רע/ה, אני טיפש/ה, הורס/ת את מה שיצר/ה, מוותר/ת מראש.", "8-12": "ביקורת עצמית קשה, אדישות מופגנת, דחיית מחמאות, הסתגרות."}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, draft = true where public.mercury_library.content is null;
insert into public.mercury_library (scope, kind, title, description, themes, category, content, draft) values ('mercury', 'calm', 'מה עוזר להירגע – זהות', 'לפתוח את מחברת החוזקות, להזכיר הצלחה קודמת, תפקיד קטן שמצליח/ה בו. משפט: גם כשקשה, את/ה חשוב/ה פה.', array['זהות ודימוי עצמי']::text[], 'זהות ודימוי עצמי', '{"bank": 1, "ages": {"2-5": "חיבוק, תזכורת למשהו טוב שעשה/תה היום, משחק שהוא/היא טוב/ה בו. משפט: ראיתי כמה ניסית.", "5-8": "לפתוח את מחברת החוזקות, להזכיר הצלחה קודמת, תפקיד קטן שמצליח/ה בו. משפט: גם כשקשה, את/ה חשוב/ה פה.", "8-12": "שיחה שמפרידה בין מעשה לזהות, הזכרת חוזקה, זמן לבד ואז חזרה. משפט: עשית טעות, את/ה לא טעות."}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, draft = true where public.mercury_library.content is null;
insert into public.mercury_library (scope, kind, title, description, themes, category, content, draft) values ('mercury', 'routine', 'שגרה – זהות', 'מחברת חוזקות שמתעדכנת פעם בשבוע. תפקיד קבוע במרכז שהוא/היא אחראי/ת עליו.', array['זהות ודימוי עצמי']::text[], 'זהות ודימוי עצמי', '{"bank": 1, "ages": {"2-5": "סיפור ערב קצר על משהו טוב שעשה/תה היום. תמונה שלו/שלה על הקיר או המיטה.", "5-8": "מחברת חוזקות שמתעדכנת פעם בשבוע. תפקיד קבוע במרכז שהוא/היא אחראי/ת עליו.", "8-12": "חוזקת השבוע. בחירה שבועית אמיתית בפעילות. מקום אישי לחפצים ולתמונות."}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, draft = true where public.mercury_library.content is null;
insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'plan', 'תכנית: זהות ודימוי עצמי', '[שם] רואה את עצמו/עצמה בצורה קשה ושלילית. כרגע הכי חשוב לעזור ל[שם] לגלות חוזקות, להתמודד עם טעויות בלי בושה ולהרגיש שהקול שלו/שלה נשמע. [מה כבר עוזר].', array['זהות ודימוי עצמי']::text[], 'זהות ודימוי עצמי', array['ARC', 'TF-CBT']::text[], '{"bank": 1, "summary": "[שם] רואה את עצמו/עצמה בצורה קשה ושלילית. כרגע הכי חשוב לעזור ל[שם] לגלות חוזקות, להתמודד עם טעויות בלי בושה ולהרגיש שהקול שלו/שלה נשמע. [מה כבר עוזר].", "goal_titles": ["זיהוי חוזקות אישיות", "התמודדות עם טעויות", "בחירה והבעת רצון"], "parts": {"avoid": "ממה להימנע – זהות", "signs": "אותות מוקדמים – זהות", "calm": "מה עוזר להירגע – זהות", "routine": "שגרה – זהות"}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, draft = true where public.mercury_library.content is null;
insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'goal', 'מעבר בין פעילויות', 'לעבור מפעילות לפעילות ומחדר לחדר בלי הצפה', array['מעברים ושגרה', 'ויסות רגשי']::text[], 'מעברים ושגרה', array['ARC', 'ויסות חושי']::text[], '{"bank": 1, "review": 1, "scale": ["כל מעבר מוביל להתפרצות", "עובר/ת רק עם ליווי צמוד וזמן רב", "עובר/ת עם תזכורת ותמונה", "עובר/ת עם תזכורת מילולית", "עובר/ת לבד לפי הלוח"], "avoid": "לא לקטוע פעילות פתאום; תמיד נותנים התראה", "strengths": ["גמישות", "שיתוף"], "skills": ["מעבר בלי התפרצות"], "ages": {"2-5": {"targets": "עובר/ת לפעילות הבאה אחרי שיר מעבר, ב-4 מתוך 6 מעברים ביום", "steps": ["דקות לפני מעבר ← אומרים: עוד מעט נסיים, ומראים תמונה", "בזמן המעבר ← שרים את שיר המעבר והולכים יד ביד"], "principles": "טקס קבוע לכל מעבר", "sentences": ["עוד מעט מסיימים", "שרים והולכים יחד"], "seen": "בוכה, נזרק/ת על הרצפה או בורח/ת בזמן מעבר", "needs": "התראה מראש וליווי בגוף", "why": "מעבר דורש עצירה של פעילות מתגמלת והסתגלות; טקס מספק ויסות חיצוני", "why_staff": "שיר קבוע במעבר עוזר לגוף לדעת מה בא", "method": "ARC – ויסות: טקסי מעבר"}, "5-8": {"targets": "מסיים/ת פעילות ועובר/ת אחרי התראה של 5 דקות ושעון חזותי, ב-4 מתוך 6 מעברים ביום", "steps": ["5 דקות לפני ← מפעילים שעון חזותי ומודיעים", "בסוף ← נותנים לילד/ה תפקיד במעבר: לסגור את האור, להוביל את הקבוצה"], "principles": "התראה, שעון, תפקיד", "sentences": ["עוד 5 דקות. אחר כך ארוחה", "רוצה להוביל אותנו?"], "seen": "מתווכח/ת, מבקש/ת עוד ועוד, מתפרץ/ת כשמפסיקים", "needs": "תחושת שליטה במעבר", "why": "שעון חזותי מתווך את הזמן המופשט; תפקיד מעביר מפסיביות לסוכנות", "why_staff": "כשיש לילד/ה תפקיד במעבר, הוא/היא פחות נאבק/ת בו", "method": "ויסות חושי: כלים חזותיים לזמן"}, "8-12": {"targets": "עובר/ת בין פעילויות לפי לוח הזמנים בלי ויכוח ממושך, ב-5 מתוך 6 מעברים ביום, תוך חודש", "steps": ["בבוקר ← עוברים יחד על היום ומסמנים מעברים קשים", "כשיש קושי במעבר ← מציעים משא ומתן קטן: עוד 2 דקות ואז זזים"], "principles": "שקיפות ומשא ומתן בגבולות", "sentences": ["עוד 2 דקות ואז זזים, מסכים/ה?", "איזה מעבר הכי קשה לך היום?"], "seen": "נאבק/ת במעברים, במיוחד מפעילות שהוא/היא אוהב/ת", "needs": "תכנון מראש ומקום למשא ומתן", "why": "תכנון מראש מגייס תפקודים ניהוליים ומפחית התנגדות", "why_staff": "כשמתכננים איתו/איתה את המעברים, יש פחות ריבים", "method": "ARC – מסוגלות: תכנון"}}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, draft = true where public.mercury_library.content is null;
insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'goal', 'התמודדות עם שינוי בלתי צפוי', 'להסתגל כשמשהו משתנה פתאום', array['מעברים ושגרה', 'ביטחון ויציבות']::text[], 'מעברים ושגרה', array['ARC', 'TF-CBT']::text[], '{"bank": 1, "review": 3, "scale": ["מתפרק/ת מכל שינוי", "נרגע/ת אחרי זמן רב", "מקבל/ת שינוי עם הסבר ותמיכה", "אומר/ת מה קשה בשינוי", "מסתגל/ת ומציע/ה פתרון"], "avoid": "לא להתעלם מהאכזבה; לא לומר זה לא נורא", "strengths": ["גמישות", "סבלנות"], "skills": ["מעבר בלי התפרצות"], "ages": {"2-5": {"targets": "נרגע/ת תוך 10 דקות עם מבוגר כשמשהו משתנה (מבוגר אחר, פעילות שבוטלה), ב-3 מתוך 5 פעמים", "steps": ["כשיש שינוי ← מסבירים במשפט אחד פשוט ומציעים חפץ מוכר", "נשארים קרוב עד שהילד/ה נרגע/ת"], "principles": "משפט אחד, הרבה נוכחות", "sentences": ["היום משהו אחר. אני פה איתך", "הגן נסגר היום, נשחק פה"], "seen": "בכי ממושך כשמשהו לא כרגיל", "needs": "מבוגר שמחזיק את השינוי", "why": "חוסר צפיות מפעיל מערכת דחק; נוכחות מבוגר מספקת ויסות", "why_staff": "בשינוי, הכי חשוב מבוגר רגוע לידו/לידה", "method": "ARC – התקשרות: נוכחות מווסתת"}, "5-8": {"targets": "מקבל/ת שינוי בתוכנית אחרי הסבר וחלופה, בלי התפרצות, ב-3 מתוך 5 פעמים בשבוע", "steps": ["כשיש שינוי ← מסבירים למה, מודים באכזבה ומציעים חלופה", "משתמשים בכרטיס הפתעה בלוח היום ← מתרגלים שגם הפתעות הן חלק מהיום"], "principles": "מכינים לכך שיהיו שינויים", "sentences": ["אני רואה שזה מאכזב", "במקום זה, אפשר..."], "seen": "כועס/ת ומאשים/ה כשמשהו משתנה", "needs": "הכרה באכזבה וחלופה מוחשית", "why": "הכרה רגשית יחד עם חלופה מפחיתות את חוויית האובדן", "why_staff": "כשאומרים שזה מאכזב ונותנים משהו אחר, הילד/ה נרגע/ת מהר יותר", "method": "ARC – ויסות: הכנה לשינוי"}, "8-12": {"targets": "מביע/ה במילים מה קשה בשינוי ומציע/ה פתרון אחד, ב-3 מתוך 4 שינויים, תוך 3 חודשים", "steps": ["כשיש שינוי ← שואלים: מה הכי מעצבן בזה? מה יעזור?", "בונים יחד תוכנית ב׳ לדברים שיכולים להשתנות"], "principles": "שותפות בפתרון", "sentences": ["מה הכי קשה לך בשינוי הזה?", "איזו תוכנית ב׳ יש לנו?"], "seen": "חווה שינוי כאישי, כאילו נגדו/נגדה", "needs": "כלים לחשיבה גמישה", "why": "גמישות קוגניטיבית מתורגלת דרך פתרון בעיות משותף", "why_staff": "כשיש תוכנית ב׳, שינוי מפחיד פחות", "method": "TF-CBT: פתרון בעיות"}}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, draft = true where public.mercury_library.content is null;
insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'goal', 'חילופי משמרת ופרידות קטנות', 'להיפרד ממבוגר בסוף משמרת ולקבל את המבוגר הבא', array['מעברים ושגרה', 'היקשרות וקשר עם מבוגר', 'אובדן ופרידה']::text[], 'מעברים ושגרה', array['ARC', 'Theraplay']::text[], '{"bank": 1, "review": 3, "scale": ["מתפרק/ת בכל חילופים", "נרגע/ת רק עם המבוגר הבא אחרי זמן", "נפרד/ת עם טקס ותמיכה", "נפרד/ת ומקבל/ת את הבא עם תזכורת", "נפרד/ת ומקבל/ת בקלות"], "avoid": "לא להיעלם בסוף משמרת בלי להיפרד", "strengths": ["אומץ", "גמישות"], "skills": [], "ages": {"2-5": {"targets": "נפרד/ת מהמבוגר בטקס קבוע (נשיקה באוויר, חפץ) ומקבל/ת את המבוגר הבא, ב-4 מתוך 7 ימים", "steps": ["לפני סוף משמרת ← אומרים לילד/ה שעוד מעט הולכים ומי יבוא", "טקס פרידה קבוע ← מעבירים את הילד/ה ישירות למבוגר הבא"], "principles": "פרידה ברורה ועקבית, תמיד", "sentences": ["עכשיו אני הביתה, ומחר שוב פה", "עכשיו [שם המבוגר] איתך"], "seen": "נצמד/ת ובוכה כשמבוגר הולך", "needs": "פרידה צפויה והעברה חמה", "why": "פרידות צפויות ועקביות מלמדות שקשר נמשך גם בהיעדר", "why_staff": "פרידה קבועה בסוף כל משמרת מלמדת שאנשים חוזרים", "method": "Theraplay: טקסי פרידה ומפגש"}, "5-8": {"targets": "יודע/ת מי במשמרת הבאה ומקבל/ת את המבוגר הבא בלי התפרצות, ב-5 מתוך 7 ימים", "steps": ["מתלים לוח של מי במשמרת היום ← מראים לילד/ה בכל חילוף", "המבוגר היוצא מעביר מילה טובה למבוגר הנכנס מול הילד/ה"], "principles": "העברה גלויה וחמה", "sentences": ["סיפרתי ל[שם המבוגר] כמה עזרת היום", "מחר אני חוזר/ת"], "seen": "מתקשה עם מבוגרים חדשים, בודק/ת אותם", "needs": "רצף בין המבוגרים", "why": "העברה חמה בין מטפלים יוצרת חוויה של מעטפת מחזיקה אחת", "why_staff": "כשאנחנו מעבירים את הילד/ה ביד חמה, הוא/היא מרגיש/ה שכולנו צוות אחד", "method": "ARC – התקשרות: עקביות בין מבוגרים"}, "8-12": {"targets": "נפרד/ת ומקבל/ת מבוגרים בחילופי משמרת בלי התנהגות מאתגרת, ב-6 מתוך 7 ימים, תוך 3 חודשים", "steps": ["המבוגר היוצא אומר שלום ומתי יחזור", "המבוגר הנכנס מתחיל בשיחה קצרה: איך היה היום?"], "principles": "כבוד: לא נעלמים, לא מתעלמים", "sentences": ["נתראה ביום ראשון", "שמעתי שהיה לך יום טוב"], "seen": "מתנהג/ת באופן מאתגר דווקא בחילופים", "needs": "תחושה שרואים אותו/אותה גם בחילופים", "why": "חילופים מעוררים חוויות אובדן; פרידה מכבדת מפחיתה ביטוי התנהגותי", "why_staff": "שלום ולהתראות בכל חילוף חוסכים הרבה התנהגות קשה", "method": "ARC – התקשרות: שגרות"}}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, draft = true where public.mercury_library.content is null;
insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'goal', 'השתתפות בשגרת היום', 'להשתתף בשגרת הבוקר, הארוחות והערב', array['מעברים ושגרה', 'שינה ואכילה']::text[], 'מעברים ושגרה', array['ARC', 'NMT']::text[], '{"bank": 1, "review": 3, "scale": ["מסרב/ת לכל חלק בשגרה", "משתתף/ת עם ליווי צמוד", "משתתף/ת עם תזכורות", "משתתף/ת עם תזכורת אחת", "מבצע/ת את השגרה לבד"], "avoid": "לא להפוך את השגרה למאבק כוח; מציעים בחירה בתוך השגרה", "strengths": ["אחריות", "התמדה"], "skills": [], "ages": {"2-5": {"targets": "משתתף/ת בשגרת הבוקר (צחצוח, לבוש) עם מבוגר ותמונות, ב-5 מתוך 7 ימים", "steps": ["תולים כרטיסי תמונה של שלבי הבוקר ← עוברים עליהם יחד", "כל שלב שהסתיים ← מסמנים יחד ומשבחים"], "principles": "תמונות, חזרתיות, הנאה", "sentences": ["עכשיו מצחצחים. אחר כך בגדים", "סיימנו! איזה יופי"], "seen": "בורח/ת, מסרב/ת להתלבש", "needs": "רצף ברור ונעים", "why": "שגרה צפויה מפחיתה עומס וויסות חיצוני משמש בסיס לעצמאות", "why_staff": "תמונות של שלבי הבוקר חוסכות הרבה מאבקים", "method": "ARC – ויסות: שגרה"}, "5-8": {"targets": "מבצע/ת את שגרת הבוקר והערב לפי לוח עם תזכורת אחת, ב-5 מתוך 7 ימים", "steps": ["לוח שגרה אישי ← הילד/ה מסמן/ת כל שלב", "בחירות קטנות בתוך השגרה: איזה בגד, איזו משחת שיניים"], "principles": "עצמאות בתוך מבנה", "sentences": ["מה השלב הבא בלוח?", "בחרת לבד, כל הכבוד"], "seen": "צריך/ה הרבה תזכורות, מתנגד/ת", "needs": "תחושת שליטה בתוך המבנה", "why": "שילוב מבנה ובחירה מפחית מאבקי כוח ומחזק תפקוד עצמאי", "why_staff": "כשיש בחירה בתוך השגרה, יש פחות התנגדות", "method": "ARC – מסוגלות: עצמאות"}, "8-12": {"targets": "מנהל/ת שגרת בוקר וערב לבד, כולל הכנת תיק, ב-6 מתוך 7 ימים, תוך 3 חודשים", "steps": ["מסכמים יחד רשימת בדיקה אישית ← הילד/ה מחזיק/ה אותה", "פעם בשבוע ← בודקים יחד מה עבד ומה צריך לשנות"], "principles": "אחריות אישית עם גיבוי", "sentences": ["איך הלך הבוקר?", "מה נשנה ברשימה?"], "seen": "שוכח/ת, מתעכב/ת, מגיע/ה באיחור", "needs": "כלי ארגון וגיבוי שבועי", "why": "פיתוח תפקודים ניהוליים דורש תרגול עם פיגום הדרגתי", "why_staff": "רשימה שהילד/ה בנה/תה בעצמו/בעצמה עובדת יותר טוב מתזכורות שלנו", "method": "NMT: חיזוק תפקודים עליונים אחרי ויסות"}}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, draft = true where public.mercury_library.content is null;
insert into public.mercury_library (scope, kind, title, description, themes, category, content, draft) values ('mercury', 'avoid', 'ממה להימנע – מעברים', 'לא להודיע על שינוי ברגע האחרון. לא להתווכח באמצע המעבר. לא להעניש על איטיות.', array['מעברים ושגרה']::text[], 'מעברים ושגרה', '{"bank": 1, "ages": {"2-5": "לא לקטוע פעילות בלי התראה. לא לגרור בכוח. לא לשנות את סדר השגרה בלי צורך.", "5-8": "לא להודיע על שינוי ברגע האחרון. לא להתווכח באמצע המעבר. לא להעניש על איטיות.", "8-12": "לא לשנות תוכניות בלי הסבר. לא להשוות לילדים אחרים בשגרה. לא לעשות מאבק כוח מול הקבוצה."}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, draft = true where public.mercury_library.content is null;
insert into public.mercury_library (scope, kind, title, description, themes, category, content, draft) values ('mercury', 'signs', 'אותות מוקדמים – מעברים', 'מבקש/ת עוד ועוד, מתווכח/ת, מאט/ה בכוונה, מתעצבן/ת.', array['מעברים ושגרה']::text[], 'מעברים ושגרה', '{"bank": 1, "ages": {"2-5": "נאחז/ת בצעצוע, בוכה כשמתקרבים, בורח/ת לפינה.", "5-8": "מבקש/ת עוד ועוד, מתווכח/ת, מאט/ה בכוונה, מתעצבן/ת.", "8-12": "מתעלם/ת מבקשות, עונה בעוקצנות, מתנגד/ת בשתיקה."}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, draft = true where public.mercury_library.content is null;
insert into public.mercury_library (scope, kind, title, description, themes, category, content, draft) values ('mercury', 'calm', 'מה עוזר להירגע – מעברים', 'שעון חזותי, תפקיד במעבר, לוח היום. משפט: עוד 5 דקות, ואז את/ה מוביל/ה.', array['מעברים ושגרה']::text[], 'מעברים ושגרה', '{"bank": 1, "ages": {"2-5": "שיר מעבר קבוע, חפץ שמעבירים מחדר לחדר, יד ביד. משפט: עכשיו הולכים יחד.", "5-8": "שעון חזותי, תפקיד במעבר, לוח היום. משפט: עוד 5 דקות, ואז את/ה מוביל/ה.", "8-12": "התראה מראש, משא ומתן קצר, הסבר. משפט: עוד 2 דקות ואז זזים, מסכים/ה?"}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, draft = true where public.mercury_library.content is null;
insert into public.mercury_library (scope, kind, title, description, themes, category, content, draft) values ('mercury', 'routine', 'שגרה – מעברים', 'לוח שגרה אישי עם סימונים. שעון חזותי. לוח של מי במשמרת.', array['מעברים ושגרה']::text[], 'מעברים ושגרה', '{"bank": 1, "ages": {"2-5": "לוח יום בתמונות. שיר לכל מעבר. אותו סדר בבוקר ובערב.", "5-8": "לוח שגרה אישי עם סימונים. שעון חזותי. לוח של מי במשמרת.", "8-12": "רשימת בדיקה אישית. תכנון שבועי. התראה על כל שינוי."}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, draft = true where public.mercury_library.content is null;
insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'plan', 'תכנית: מעברים ושגרה', '[שם] מתקשה במעברים ובשינויים, וזה מתבטא ב[איך זה נראה]. כרגע הכי חשוב לבנות ל[שם] יום צפוי, טקסי מעבר וחילופי משמרת חמים. [מה כבר עוזר].', array['מעברים ושגרה']::text[], 'מעברים ושגרה', array['ARC']::text[], '{"bank": 1, "summary": "[שם] מתקשה במעברים ובשינויים, וזה מתבטא ב[איך זה נראה]. כרגע הכי חשוב לבנות ל[שם] יום צפוי, טקסי מעבר וחילופי משמרת חמים. [מה כבר עוזר].", "goal_titles": ["מעבר בין פעילויות", "חילופי משמרת ופרידות קטנות", "ניבוי והכנה מראש"], "parts": {"avoid": "ממה להימנע – מעברים", "signs": "אותות מוקדמים – מעברים", "calm": "מה עוזר להירגע – מעברים", "routine": "שגרה – מעברים"}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, draft = true where public.mercury_library.content is null;
insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'goal', 'משחק משותף ותור', 'לשחק עם ילדים אחרים, לחכות לתור ולשתף', array['קשרים חברתיים']::text[], 'קשרים חברתיים', array['Theraplay', 'ARC']::text[], '{"bank": 1, "review": 3, "scale": ["משחק/ת רק לבד או חוטף/ת", "משחק/ת ליד ילדים בלי קשר", "משחק/ת עם ילד אחד בליווי מבוגר", "משחק/ת בקבוצה קטנה עם תזכורות", "משחק/ת, מחכה ומשתף/ת לבד"], "avoid": "לא לחייב לשתף חפץ אישי או חפץ מעבר", "strengths": ["שיתוף", "סבלנות"], "skills": ["המתנה לתור"], "ages": {"2-5": {"targets": "משחק/ת ליד ילד אחר או איתו 5 דקות עם מבוגר בקרבת מקום, ב-4 מתוך 7 ימים", "steps": ["מושיבים שני ילדים עם אותו משחק ← המבוגר משחק איתם ומתווך", "כשהילד/ה חוטף/ת ← עוצרים בעדינות ומראים: מבקשים, ומחכים"], "principles": "המבוגר משחק בפנים ומתווך", "sentences": ["עכשיו התור שלו, אחר כך שלך", "בוא/י נבנה ביחד"], "seen": "חוטף/ת צעצועים, דוחף/ת, משחק/ת רק לבד", "needs": "מבוגר שמתווך את המשחק המשותף", "why": "מיומנויות משחק משותף נלמדות תחילה בתיווך מבוגר", "why_staff": "כשאנחנו משחקים יחד עם הילדים, הם לומדים לשחק אחד עם השני", "method": "Theraplay: משחק קבוצתי מובנה"}, "5-8": {"targets": "משחק/ת משחק עם כללים בקבוצה של 2–3 ילדים ומחכה לתור, ב-3 מתוך 5 פעמים", "steps": ["לפני המשחק ← מזכירים כלל אחד: מחכים לתור", "כשהילד/ה מחכה ← משבחים מיד ובמדויק"], "principles": "כלל אחד, הרבה שבח", "sentences": ["ראיתי שחיכית לתור, כל הכבוד", "גם להפסיד זה חלק מהמשחק"], "seen": "מתקשה להפסיד, עוזב/ת משחק בכעס", "needs": "תרגול מובנה של המתנה והפסד", "why": "משחק עם כללים מתרגל עיכוב תגובה וויסות בתוך הקשר חברתי", "why_staff": "כל פעם שמחכה לתור ומקבל/ת שבח, קל יותר בפעם הבאה", "method": "ARC – ויסות בתוך קשר"}, "8-12": {"targets": "משתתף/ת במשחק או בפעילות קבוצתית עד הסוף, כולל הפסד, ב-3 מתוך 4 פעמים", "steps": ["לפני משחק תחרותי ← שואלים: מה תעשה/תעשי אם תפסיד/י?", "אחרי ← מסכמים יחד מה היה טוב בהתנהגות, לא רק בתוצאה"], "principles": "מתכננים מראש את ההתמודדות", "sentences": ["מה התוכנית שלך אם תפסיד/י?", "שיחקת יפה גם כשהפסדת"], "seen": "רמאות, התפרצות בהפסד, עזיבת הקבוצה", "needs": "תוכנית התמודדות ולהרגיש שייך/ת", "why": "תכנון מראש מגייס חשיבה לפני הרגש; השתייכות לקבוצה היא צורך מרכזי בגיל", "why_staff": "כשמתכננים מראש מה עושים בהפסד, יש פחות פיצוצים", "method": "ARC – מסוגלות: כישורים חברתיים"}}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, draft = true where public.mercury_library.content is null;
insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'goal', 'פתרון מחלוקות במילים', 'לפתור ריב עם ילד אחר במילים ולא בידיים', array['קשרים חברתיים', 'התנהגות מסכנת וגבולות']::text[], 'קשרים חברתיים', array['TF-CBT', 'ARC']::text[], '{"bank": 1, "review": 3, "scale": ["מכה או מקלל/ת מיד", "מתפרץ/ת ונרגע/ת עם מבוגר", "קורא/ת למבוגר כשיש ריב", "אומר/ת במילים מה מפריע", "מציע/ה פתרון ומתפשר/ת"], "avoid": "לא לחפש אשם ולא לדרוש סליחה מיד", "strengths": ["שליטה עצמית", "הקשבה"], "skills": ["פתרון בעיה במילים"], "ages": {"2-5": {"targets": "קורא/ת למבוגר או אומר/ת די! כשילד אחר לוקח או דוחף (במקום להכות), ב-3 מתוך 5 פעמים", "steps": ["כשיש ריב ← ניגשים מהר, עוצרים את הידיים בעדינות ונותנים מילים: תגיד/י: זה שלי", "מלמדים מילה קבועה: די! וקריאה למבוגר"], "principles": "המבוגר נותן מילים במקום ידיים", "sentences": ["תגיד/י לו: זה שלי", "אפשר לקרוא לי כשמישהו מפריע"], "seen": "מכה, נושך/ת או דוחף/ת", "needs": "מילים פשוטות ומבוגר קרוב", "why": "בגיל הזה השפה מחליפה בהדרגה את הפעולה הגופנית", "why_staff": "כל פעם שנותנים מילים במקום מכה, הילד/ה לומד/ת דרך אחרת", "method": "ARC – ויסות: מילים במקום גוף"}, "5-8": {"targets": "אומר/ת במילים מה מפריע לו/לה בריב, עם מבוגר שמתווך, ב-3 מתוך 5 ריבים בשבוע", "steps": ["בריב ← מפרידים, נותנים לכל ילד לומר מה קרה ומה הוא רוצה", "מציעים שתי דרכים לפתור ונותנים לילדים לבחור"], "principles": "כל צד נשמע, הילדים בוחרים פתרון", "sentences": ["מה רצית שיקרה?", "יש לי שני רעיונות. איזה מתאים?"], "seen": "מאשים/ה, צועק/ת, מסרב/ת לשמוע את הצד השני", "needs": "מבנה ברור לפתרון מחלוקת", "why": "גישור מובנה מתרגל נקודת מבט של האחר ופתרון בעיות", "why_staff": "כשכל ילד נשמע, הריב נגמר מהר יותר", "method": "TF-CBT: פתרון בעיות"}, "8-12": {"targets": "פותר/ת מחלוקת עם ילד אחר במילים ובפשרה בלי מבוגר שמתערב, לפחות פעמיים בשבוע", "steps": ["מלמדים ארבעה צעדים: לעצור, לומר מה מפריע, להקשיב, להציע פתרון", "אחרי ריב שנפתר לבד ← משבחים בפרטיות"], "principles": "עצמאות בפתרון, שבח בפרטיות", "sentences": ["ראיתי שפתרתם את זה לבד", "מה הייתה הפשרה?"], "seen": "מסלים/ה ריבים, נכנס/ת לעימות פיזי", "needs": "כלים לפתרון עצמאי", "why": "מיומנויות פתרון קונפליקט מפחיתות תוקפנות ומחזקות מעמד חברתי", "why_staff": "ילד/ה שיודע/ת לפתור לבד, צריך/ה אותנו פחות בריבים", "method": "TF-CBT: מיומנויות בין-אישיות"}}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, draft = true where public.mercury_library.content is null;
insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'goal', 'יצירת קשר עם ילד חדש', 'לפנות לילד/ה ולהזמין למשחק, ולהצטרף למשחק של אחרים', array['קשרים חברתיים', 'זהות ודימוי עצמי']::text[], 'קשרים חברתיים', array['Theraplay', 'ARC']::text[], '{"bank": 1, "review": 3, "scale": ["לא פונה לילדים", "מצטרף/ת רק כשמבוגר מזמין", "מצטרף/ת למשחק כשמזמינים", "שואל/ת אם אפשר להצטרף", "מזמין/ה ויוזם/ת קשר"], "avoid": "לא לחייב להצטרף לקבוצה; מזמינים ומחכים", "strengths": ["אומץ", "חברות"], "skills": [], "ages": {"2-5": {"targets": "מצטרף/ת למשחק של ילד אחר כשמבוגר מזמין, ב-3 מתוך 5 פעמים", "steps": ["המבוגר מתיישב ליד ילדים שמשחקים ← מזמין את הילד/ה לשבת לידו", "נותנים לילד/ה תפקיד קטן במשחק: את/ה מביא/ה את הקוביות"], "principles": "מצטרפים דרך המבוגר", "sentences": ["בוא/י נשב פה ליד", "רוצה לעזור בבנייה?"], "seen": "מסתכל/ת מהצד, לא מצטרף/ת", "needs": "גשר דרך מבוגר", "why": "הצטרפות מתווכת מפחיתה חרדה חברתית", "why_staff": "קל להצטרף כשמבוגר עוזר להיכנס", "method": "Theraplay: מעורבות קבוצתית"}, "5-8": {"targets": "שואל/ת ילד אחר אפשר לשחק? או מזמין/ה למשחק, לפחות פעמיים בשבוע", "steps": ["מתרגלים במשחק תפקידים איך שואלים ומה עונים", "כשהילד/ה מנסה ← מלווים מקרוב ומשבחים את הניסיון"], "principles": "מתרגלים, מנסים, משבחים את הניסיון", "sentences": ["רוצה לשאול אם אפשר להצטרף?", "ניסית, זה היה אמיץ"], "seen": "נכנס/ת למשחק בכוח או נשאר/ת בצד", "needs": "משפטי פתיחה וליווי", "why": "מיומנויות פנייה חברתית נלמדות בתרגול ובחיזוק", "why_staff": "משפט פתיחה שמתרגלים איתנו עוזר לפנות לילדים", "method": "ARC – מסוגלות: כישורים חברתיים"}, "8-12": {"targets": "יוזם/ת פעילות עם ילד אחר או מצטרף/ת לקבוצה בעצמו/בעצמה, לפחות 3 פעמים בשבוע", "steps": ["מזהים יחד ילד עם תחום עניין דומה ← יוצרים הזדמנות לפעילות משותפת", "מדברים בפרטיות על מה עבד ומה היה מביך"], "principles": "יוצרים הזדמנויות, לא מכריחים", "sentences": ["נראה לי שגם הוא אוהב כדורגל", "איך היה לשחק איתם?"], "seen": "בודד/ה, או מנסה להשתייך בדרכים מסוכנות", "needs": "הזדמנויות לקשר סביב תחומי עניין", "why": "קשרי עמיתים הם גורם חוסן משמעותי בגיל הזה", "why_staff": "חבר אחד טוב במרכז עושה הבדל גדול", "method": "ARC – מסוגלות: השתייכות"}}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, draft = true where public.mercury_library.content is null;
insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'goal', 'הבנת רגשות של אחרים', 'לשים לב למה שאחרים מרגישים ולהגיב בהתאם', array['קשרים חברתיים', 'ויסות רגשי']::text[], 'קשרים חברתיים', array['DDP/PACE', 'TF-CBT']::text[], '{"bank": 1, "review": 3, "scale": ["לא שם/ה לב לרגשות של אחרים", "מזהה רגש של אחר כשמבוגר מצביע", "מזהה רגש בסיסי של חבר", "מגיב/ה ברגישות כשמישהו עצוב", "מבין/ה ומציע/ה עזרה"], "avoid": "לא להטיף איך הוא מרגיש בגללך; שואלים ומבינים יחד", "strengths": ["אכפתיות", "הקשבה"], "skills": [], "ages": {"2-5": {"targets": "מראה שם לב כשילד אחר בוכה (מסתכל/ת, מביא/ה צעצוע, קורא/ת למבוגר), ב-3 מתוך 5 פעמים", "steps": ["כשילד אחר בוכה ← אומרים בקול: הוא עצוב. מה יכול לעזור לו?", "משחקים בבובות שעוזרות אחת לשנייה"], "principles": "המבוגר מצביע על רגשות של אחרים", "sentences": ["הוא עצוב. מה יעזור לו?", "הבאת לו בובה, זה היה אכפתי"], "seen": "ממשיך/ה כאילו לא קרה כלום, או צוחק/ת", "needs": "מבוגר שמראה את הרגשות של האחרים", "why": "אמפתיה מתפתחת דרך מבוגרים שמתווכים מצבים רגשיים של אחרים", "why_staff": "כשאנחנו אומרים בקול מה חבר מרגיש, הילד/ה לומד/ת לשים לב", "method": "DDP/PACE: אמפתיה"}, "5-8": {"targets": "מזהה איך חבר מרגיש בסיטואציה ומציע/ה דרך לעזור, ב-3 מתוך 5 פעמים כשמבוגר שואל", "steps": ["כשקורה משהו בקבוצה ← שואלים: איך לדעתך הוא מרגיש?", "קוראים יחד ספרים ומדברים על רגשות הדמויות"], "principles": "שואלים, לא מטיפים", "sentences": ["איך נראה לך שהיא מרגישה?", "מה היה עוזר לך אם זה היה קורה לך?"], "seen": "מתקשה לראות את הצד השני", "needs": "תרגול נקודת מבט", "why": "תיאוריית התודעה מתפתחת בתרגול מילולי ובסיפורים", "why_staff": "שאלה פשוטה על מה חבר מרגיש מלמדת אמפתיה", "method": "TF-CBT: מיומנויות רגשיות"}, "8-12": {"targets": "מתייחס/ת ברגישות לחבר במצוקה או לוקח/ת אחריות אחרי שפגע/ה, לפחות פעמיים בשבוע", "steps": ["אחרי שפגע/ה ← שיחה קצרה: מה הוא הרגיש? מה אפשר לעשות?", "כשמגלה רגישות ← משבחים בפרטיות"], "principles": "אחריות בלי בושה", "sentences": ["מה לדעתך הוא הרגיש?", "ראיתי שעזרת לה כשהיה לה קשה"], "seen": "פוגע/ת בלי לשים לב, או מאשים/ה את הנפגע", "needs": "רפלקציה מכבדת אחרי פגיעה", "why": "חיבור בין מעשה להשפעתו על אחר מחזק מוסריות ואמפתיה", "why_staff": "שיחה רגועה על מה שהחבר הרגיש מלמדת יותר מעונש", "method": "DDP/PACE: סקרנות ואמפתיה"}}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, draft = true where public.mercury_library.content is null;
insert into public.mercury_library (scope, kind, title, description, themes, category, content, draft) values ('mercury', 'avoid', 'ממה להימנע – חברתי', 'לא לחפש אשם בריב מול כולם. לא לחייב לבקש סליחה מיד. לא להושיב ליד ילד שמפעיל אותו/אותה.', array['קשרים חברתיים']::text[], 'קשרים חברתיים', '{"bank": 1, "ages": {"2-5": "לא לחייב לשתף חפץ אישי. לא להשוות לילד אחר. לא להעניש בבידוד מהקבוצה לזמן ארוך.", "5-8": "לא לחפש אשם בריב מול כולם. לא לחייב לבקש סליחה מיד. לא להושיב ליד ילד שמפעיל אותו/אותה.", "8-12": "לא להשפיל מול חברים. לא לדבר על הילד/ה מול ילדים אחרים. לא להתעלם מחרם או מהצקות."}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, draft = true where public.mercury_library.content is null;
insert into public.mercury_library (scope, kind, title, description, themes, category, content, draft) values ('mercury', 'signs', 'אותות מוקדמים – חברתי', 'מתווכח/ת על כללים, מתלונן/ת שלא נותנים לו/לה, צוחק/ת על אחרים.', array['קשרים חברתיים']::text[], 'קשרים חברתיים', '{"bank": 1, "ages": {"2-5": "חוטף/ת, דוחף/ת, מתרחק/ת מהקבוצה, בוכה כשילד מתקרב.", "5-8": "מתווכח/ת על כללים, מתלונן/ת שלא נותנים לו/לה, צוחק/ת על אחרים.", "8-12": "התגרויות, כינויים, בדידות, נגררות אחרי ילדים במצבים מסוכנים."}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, draft = true where public.mercury_library.content is null;
insert into public.mercury_library (scope, kind, title, description, themes, category, content, draft) values ('mercury', 'calm', 'מה עוזר להירגע – חברתי', 'הפרדה קצרה, לשמוע כל צד, להציע פתרון. משפט: אני שומע/ת אותך, בוא/י נמצא פתרון.', array['קשרים חברתיים']::text[], 'קשרים חברתיים', '{"bank": 1, "ages": {"2-5": "מבוגר שמתווך, הפרדה קצרה ומשחק לידו/לידה. משפט: אני עוזר/ת לכם לשחק יחד.", "5-8": "הפרדה קצרה, לשמוע כל צד, להציע פתרון. משפט: אני שומע/ת אותך, בוא/י נמצא פתרון.", "8-12": "שיחה בפרטיות, זמן להירגע, חזרה לקבוצה עם תוכנית. משפט: מה יעזור לך לחזור לקבוצה?"}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, draft = true where public.mercury_library.content is null;
insert into public.mercury_library (scope, kind, title, description, themes, category, content, draft) values ('mercury', 'routine', 'שגרה – חברתי', 'משחק קופסה עם מבוגר פעמיים בשבוע. תפקיד קבוצתי קבוע.', array['קשרים חברתיים']::text[], 'קשרים חברתיים', '{"bank": 1, "ages": {"2-5": "משחק קבוצתי קצר ומובנה כל יום. אותם 2–3 ילדים בפינת משחק.", "5-8": "משחק קופסה עם מבוגר פעמיים בשבוע. תפקיד קבוצתי קבוע.", "8-12": "פעילות קבוצתית שבועית סביב תחום עניין. הזדמנות לעזור לילד צעיר יותר."}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, draft = true where public.mercury_library.content is null;
insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'plan', 'תכנית: קשרים חברתיים', '[שם] מתקשה במשחק ובקשר עם ילדים, וזה מתבטא ב[איך זה נראה]. כרגע הכי חשוב לעזור ל[שם] לשחק בתור, לפתור ריבים במילים ולמצוא חבר. [מה כבר עוזר].', array['קשרים חברתיים']::text[], 'קשרים חברתיים', array['Theraplay', 'TF-CBT']::text[], '{"bank": 1, "summary": "[שם] מתקשה במשחק ובקשר עם ילדים, וזה מתבטא ב[איך זה נראה]. כרגע הכי חשוב לעזור ל[שם] לשחק בתור, לפתור ריבים במילים ולמצוא חבר. [מה כבר עוזר].", "goal_titles": ["משחק משותף ותור", "פתרון מחלוקות במילים", "זיהוי ושיום רגשות"], "parts": {"avoid": "ממה להימנע – חברתי", "signs": "אותות מוקדמים – חברתי", "calm": "מה עוזר להירגע – חברתי", "routine": "שגרה – חברתי"}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, draft = true where public.mercury_library.content is null;
insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'goal', 'השתתפות בפעילות לימודית', 'להשתתף בפעילות לימודית או יצירתית לזמן שמתאים לגיל', array['למידה ותפקוד']::text[], 'למידה ותפקוד', array['NMT', 'ויסות חושי', 'ARC']::text[], '{"bank": 1, "review": 3, "scale": ["מסרב/ת להשתתף", "משתתף/ת דקות ספורות עם מבוגר צמוד", "משתתף/ת חצי מהזמן עם עידוד", "משתתף/ת רוב הזמן עם תזכורות", "משתתף/ת לאורך כל הפעילות"], "avoid": "לא לדרוש ישיבה ממושכת כשהגוף לא מווסת; קודם תנועה", "strengths": ["סקרנות", "התמדה"], "skills": [], "ages": {"2-5": {"targets": "משתתף/ת בפעילות קבוצתית (שיר, סיפור, יצירה) 5–10 דקות, ב-4 מתוך 5 ימים", "steps": ["לפני הפעילות ← משחק תנועה קצר (קפיצות, ריקוד)", "בזמן הפעילות ← מושיבים קרוב למבוגר ונותנים חפץ קטן להחזיק"], "principles": "קודם הגוף, אחר כך הלמידה", "sentences": ["בוא/י נשב יחד ונשמע סיפור", "את/ה יכול/ה להחזיק את זה בזמן הסיפור"], "seen": "קם/ה כל הזמן, לא מצליח/ה לשבת", "needs": "תנועה וויסות לפני ישיבה", "why": "בלי ויסות גופי בסיסי אין פניות לקשב וללמידה", "why_staff": "דקה של תנועה לפני פעילות עוזרת לשבת אחר כך", "method": "NMT: ויסות לפני למידה"}, "5-8": {"targets": "משתתף/ת בפעילות לימודית של 15 דקות עם הפסקת תנועה אחת, ב-4 מתוך 5 ימים", "steps": ["מחלקים פעילות לחלקים קצרים ← הפסקת תנועה בין החלקים", "נותנים כלי ויסות שקט ליד השולחן (כדור לחיץ, כרית ישיבה)"], "principles": "חלקים קצרים והפסקות מתוכננות", "sentences": ["עוד שני תרגילים ואז הפסקה", "רוצה את הכרית?"], "seen": "מסיח/ה את הדעת, עוזב/ת את השולחן", "needs": "מבנה של חלקים קצרים וויסות חושי", "why": "חלונות קשב קצרים עם הפסקות מווסתות תואמים את היכולת ומגדילים אותה בהדרגה", "why_staff": "פעילות קצרה עם הפסקה עובדת יותר טוב מפעילות ארוכה בכוח", "method": "ויסות חושי: כלים ליד השולחן"}, "8-12": {"targets": "עובד/ת על שיעורי בית או משימה 25 דקות ברצף, עם הפסקה שהוא/היא מבקש/ת, ב-4 מתוך 5 ימים", "steps": ["מתכננים יחד: כמה זמן, מה הסדר, מתי הפסקה", "בזמן העבודה ← המבוגר בקרבת מקום, זמין לשאלות, לא מעל הראש"], "principles": "תכנון משותף ונוכחות לא פולשנית", "sentences": ["מה התוכנית שלך להיום?", "אני פה אם צריך/ה"], "seen": "דוחה, מתחמק/ת, אומר/ת אין לי שיעורים", "needs": "תכנון ותחושת מסוגלות בלמידה", "why": "פערים לימודיים וחוויות כישלון מובילים להימנעות; הצלחות קטנות מתוכננות שוברות את המעגל", "why_staff": "כשיש תוכנית ברורה ומבוגר בסביבה, קל יותר להתחיל", "method": "ARC – מסוגלות: תפקודים ניהוליים"}}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, draft = true where public.mercury_library.content is null;
insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'goal', 'בקשת עזרה בלמידה', 'לבקש עזרה כשלא מבינים, במקום לוותר או להתפרץ', array['למידה ותפקוד', 'ויסות רגשי']::text[], 'למידה ותפקוד', array['ARC', 'TF-CBT']::text[], '{"bank": 1, "review": 1, "scale": ["מתפרץ/ת או מוותר/ת כשלא מבין/ה", "עוצר/ת ומחכה שמבוגר יבחין", "מבקש/ת עזרה בסימן", "מבקש/ת עזרה במילים", "שואל/ת שאלה ממוקדת"], "avoid": "לא לומר אבל הסברתי כבר; מסבירים שוב, אחרת", "strengths": ["בקשת עזרה", "אומץ"], "skills": ["בקשת עזרה"], "ages": {"2-5": {"targets": "מביא/ה למבוגר משהו שלא מצליח/ה לעשות (פאזל, קופסה) במקום לזרוק, ב-3 מתוך 5 פעמים", "steps": ["כשהילד/ה נאבק/ת במשהו ← ניגשים ושואלים: רוצה עזרה?", "עוזרים בחלק ומשאירים לו/לה לסיים"], "principles": "עוזרים קצת, משאירים את ההצלחה לילד/ה", "sentences": ["רוצה עזרה?", "את החלק האחרון את/ה עושה"], "seen": "זורק/ת חפצים כשלא מצליח/ה", "needs": "לחוות שעזרה עוזרת", "why": "בקשת עזרה היא אסטרטגיה התקשרותית וקוגניטיבית כאחד", "why_staff": "כשעוזרים רק קצת, הילד/ה מרגיש/ה שהצליח/ה בעצמו/בעצמה", "method": "ARC – מסוגלות"}, "5-8": {"targets": "מרים/ה יד או משתמש/ת בכרטיס עזרה כשלא מבין/ה, ב-3 מתוך 5 פעמים בשבוע", "steps": ["מניחים כרטיס עזרה על השולחן ← מסבירים שאפשר להפוך אותו", "כשמשתמש/ת בכרטיס ← מגיעים מהר ומשבחים את הבקשה"], "principles": "בקשה קלה ותגובה מהירה", "sentences": ["ראיתי את הכרטיס, אני בא/ה", "טוב ששאלת"], "seen": "מתבייש/ת לשאול, מעתיק/ה או מוותר/ת", "needs": "דרך לא מביכה לבקש", "why": "כרטיס עזרה מפחית חשיפה חברתית ובושה", "why_staff": "כרטיס על השולחן מאפשר לבקש עזרה בלי שכולם ישמעו", "method": "ARC – מסוגלות: כלים לבקשת עזרה"}, "8-12": {"targets": "שואל/ת שאלה ממוקדת (מה אני לא מבין/ה) כשנתקע/ת, לפחות 3 פעמים בשבוע", "steps": ["כשהילד/ה נתקע/ת ← שואלים: מה החלק שעוד לא ברור?", "מלמדים לנסח: הבנתי את... לא הבנתי את..."], "principles": "מכוונים לשאלה מדויקת", "sentences": ["איזה חלק עוד לא ברור?", "שאלה טובה. בוא/י נפרק"], "seen": "אומר/ת אני לא מבין/ה כלום ונסגר/ת", "needs": "כלי לנסח מה לא ברור", "why": "ניסוח שאלה ממוקדת מחזק מטה-קוגניציה ומפחית הצפה", "why_staff": "כשהילד/ה יודע/ת מה בדיוק לא ברור, קל לעזור", "method": "TF-CBT: פתרון בעיות"}}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, draft = true where public.mercury_library.content is null;
insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'goal', 'קשב והתמדה במשימה', 'להתרכז במשימה ולהמשיך עד הסוף', array['למידה ותפקוד', 'ויסות רגשי']::text[], 'למידה ותפקוד', array['NMT', 'ויסות חושי']::text[], '{"bank": 1, "review": 3, "scale": ["עוזב/ת כל משימה תוך דקה", "מתמיד/ה כמה דקות עם מבוגר צמוד", "מסיים/ת משימה קצרה עם עידוד", "מסיים/ת משימה עם תזכורת אחת", "מסיים/ת משימות לבד"], "avoid": "לא לתת כמה הוראות בבת אחת", "strengths": ["התמדה", "אחריות"], "skills": [], "ages": {"2-5": {"targets": "מסיים/ת משימה קצרה (פאזל קטן, ציור) עד הסוף עם מבוגר לידו/לידה, ב-3 מתוך 5 פעמים", "steps": ["בוחרים משימה קצרה מאוד ← מסיימים יחד", "כשמסיים/ת ← חוגגים: סיימת!"], "principles": "משימה קצרה שאפשר לסיים", "sentences": ["עוד חלק אחד", "סיימת! איזה יופי"], "seen": "עובר/ת ממשחק למשחק", "needs": "חוויות סיום", "why": "חוויות של השלמת משימה בונות התמדה וקשב", "why_staff": "עדיף משימה קטנה שמסתיימת מגדולה שנזנחת", "method": "NMT: הצלחות קטנות וחוזרות"}, "5-8": {"targets": "מסיים/ת משימה של 10 דקות עם הוראה אחת בכל פעם, ב-4 מתוך 5 פעמים", "steps": ["נותנים הוראה אחת ← מחכים לביצוע ואז נותנים את הבאה", "משתמשים ברשימת צעדים בתמונות"], "principles": "הוראה אחת בכל פעם", "sentences": ["קודם זה. אחר כך אגיד את הבא", "ראיתי שהמשכת עד הסוף"], "seen": "שוכח/ת הוראות, מתבלבל/ת", "needs": "הוראות קצרות ורצף ברור", "why": "זיכרון עבודה נפגע בדחק; פירוק הוראות מפחית עומס", "why_staff": "הוראה אחת בכל פעם, במקום שלוש בבת אחת", "method": "ויסות חושי: הפחתת עומס"}, "8-12": {"targets": "מתכנן/ת ומסיים/ת משימה של 30 דקות בעזרת רשימה, ב-3 מתוך 4 פעמים בשבוע", "steps": ["מפרקים יחד משימה גדולה לרשימת צעדים", "הילד/ה מסמן/ת כל צעד שסיים/ה"], "principles": "הילד/ה מנהל/ת את הרשימה", "sentences": ["איזה צעד הבא ברשימה?", "סימנת כבר שלושה, יפה"], "seen": "מתחיל/ה ולא מסיים/ת", "needs": "כלי ארגון", "why": "רשימות חיצוניות מפצות על קשיי ארגון ומחזקות תפקוד ניהולי", "why_staff": "רשימה שהילד/ה מסמן/ת עוזרת להמשיך", "method": "NMT: תפקודים עליונים"}}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, draft = true where public.mercury_library.content is null;
insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'goal', 'מוכנות לבית הספר או לגן', 'לצאת בבוקר לבית הספר או לגן מוכן/ה ובזמן', array['למידה ותפקוד', 'מעברים ושגרה']::text[], 'למידה ותפקוד', array['ARC']::text[], '{"bank": 1, "review": 3, "scale": ["מסרב/ת לצאת", "יוצא/ת באיחור ובמאבק", "יוצא/ת בזמן עם הרבה עזרה", "יוצא/ת בזמן עם תזכורות", "מתארגן/ת ויוצא/ת לבד"], "avoid": "לא להתחיל את הבוקר בצעקות או באיומים", "strengths": ["אחריות", "התמדה"], "skills": [], "ages": {"2-5": {"targets": "יוצא/ת לגן עם מבוגר בלי בכי ממושך, ב-4 מתוך 5 ימים", "steps": ["בערב ← מכינים יחד את התיק ובוחרים בגד", "בבוקר ← שיר קבוע בדרך לגן וטקס פרידה בכניסה"], "principles": "הכנה בערב, טקס בבוקר", "sentences": ["מחר גן! בוא/י נכין את התיק", "אחרי הגן אני מחכה לך פה"], "seen": "בוכה בפרידה בגן, מסרב/ת להתלבש", "needs": "פרידה צפויה והבטחה שחוזרים", "why": "חרדת פרידה מוגברת בילדים עם טראומה; טקס פרידה מספק ניבוי", "why_staff": "טקס קבוע בכניסה לגן עוזר להיפרד", "method": "ARC – ויסות: טקסי פרידה"}, "5-8": {"targets": "מוכן/ה ליציאה לבית הספר בזמן לפי לוח בוקר, ב-4 מתוך 5 ימים", "steps": ["לוח בוקר בתמונות ← הילד/ה מסמן/ת כל שלב", "שואלים בערב: יש משהו שמדאיג אותך מחר בבית הספר?"], "principles": "מבנה בבוקר, הקשבה בערב", "sentences": ["מה הבא בלוח?", "יש משהו שמדאיג אותך מחר?"], "seen": "כאבי בטן בבוקר, התעכבות", "needs": "מבנה וטיפול בדאגות מראש", "why": "תלונות גופניות בבוקר הן לעיתים ביטוי לחרדה; הקשבה מוקדמת מפחיתה הימנעות", "why_staff": "כאב בטן בבוקר הוא לפעמים דאגה. כדאי לשאול בערב", "method": "ARC – ויסות"}, "8-12": {"targets": "מתארגן/ת לבד (תיק, לבוש, ארוחה) ויוצא/ת בזמן, ב-4 מתוך 5 ימים, תוך 3 חודשים", "steps": ["רשימת בדיקה שהילד/ה בנה/תה ← נבדקת בערב", "קשר שבועי עם בית הספר ← משתפים את הילד/ה במה שנאמר"], "principles": "אחריות אישית ושקיפות", "sentences": ["בדקת את הרשימה?", "דיברתי עם המחנכת, רוצה לשמוע?"], "seen": "מאחר/ת, שוכח/ת ציוד, נמנע/ת מבית הספר", "needs": "כלי ארגון ושותפות עם בית הספר", "why": "קשר בין מסגרת המגורים לבית הספר מחזק רצף ומפחית נשירה", "why_staff": "כשהילד/ה יודע/ת שאנחנו בקשר עם בית הספר, הוא/היא מרגיש/ה שמישהו איתו/איתה", "method": "ARC – מסוגלות"}}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, draft = true where public.mercury_library.content is null;
insert into public.mercury_library (scope, kind, title, description, themes, category, content, draft) values ('mercury', 'avoid', 'ממה להימנע – למידה', 'לא לתת כמה הוראות בבת אחת. לא לומר הסברתי כבר. לא להעניש על קושי בלמידה.', array['למידה ותפקוד']::text[], 'למידה ותפקוד', '{"bank": 1, "ages": {"2-5": "לא לדרוש ישיבה ארוכה. לא לתקן כל טעות. לא להשוות ליכולות של ילדים אחרים.", "5-8": "לא לתת כמה הוראות בבת אחת. לא לומר הסברתי כבר. לא להעניש על קושי בלמידה.", "8-12": "לא לבקר מול ילדים אחרים. לא לעשות במקומו/במקומה. לא להפוך את שיעורי הבית למאבק כוח."}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, draft = true where public.mercury_library.content is null;
insert into public.mercury_library (scope, kind, title, description, themes, category, content, draft) values ('mercury', 'signs', 'אותות מוקדמים – למידה', 'אומר/ת זה משעמם או אני לא יודע/ת, מסתובב/ת, מפריע/ה לאחרים.', array['למידה ותפקוד']::text[], 'למידה ותפקוד', '{"bank": 1, "ages": {"2-5": "קם/ה ועוזב/ת, זורק/ת חומרים, בוכה מול משימה.", "5-8": "אומר/ת זה משעמם או אני לא יודע/ת, מסתובב/ת, מפריע/ה לאחרים.", "8-12": "מתחמק/ת, אומר/ת אין לי שיעורים, ראש על השולחן, תגובות עוקצניות."}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, draft = true where public.mercury_library.content is null;
insert into public.mercury_library (scope, kind, title, description, themes, category, content, draft) values ('mercury', 'calm', 'מה עוזר להירגע – למידה', 'הפסקה קצרה, כדור לחיץ, פירוק המשימה. משפט: נעשה רק את הראשון, ואז נראה.', array['למידה ותפקוד']::text[], 'למידה ותפקוד', '{"bank": 1, "ages": {"2-5": "הפסקת תנועה, מבוגר שעוזר בחלק, משימה קצרה יותר. משפט: ננסה יחד חלק אחד.", "5-8": "הפסקה קצרה, כדור לחיץ, פירוק המשימה. משפט: נעשה רק את הראשון, ואז נראה.", "8-12": "הפסקה שהוא/היא בוחר/ת, שתייה, תכנון מחדש. משפט: איזה חלק הכי קשה? נתחיל ממנו או מהקל?"}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, draft = true where public.mercury_library.content is null;
insert into public.mercury_library (scope, kind, title, description, themes, category, content, draft) values ('mercury', 'routine', 'שגרה – למידה', 'זמן שיעורים קבוע עם הפסקה. פינת עבודה שקטה. לוח בוקר לבית הספר.', array['למידה ותפקוד']::text[], 'למידה ותפקוד', '{"bank": 1, "ages": {"2-5": "פעילות קבוצתית קצרה בשעה קבועה. משחק תנועה לפני ישיבה.", "5-8": "זמן שיעורים קבוע עם הפסקה. פינת עבודה שקטה. לוח בוקר לבית הספר.", "8-12": "שעת למידה קבועה עם מבוגר זמין. רשימת בדיקה לתיק. קשר שבועי עם בית הספר."}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, draft = true where public.mercury_library.content is null;
insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'plan', 'תכנית: למידה ותפקוד', '[שם] מתקשה להתרכז ולהשתתף בלמידה, וזה מתבטא ב[איך זה נראה]. כרגע הכי חשוב לעזור ל[שם] להשתתף, לבקש עזרה ולהרגיש מצליח/ה. [מה כבר עוזר].', array['למידה ותפקוד']::text[], 'למידה ותפקוד', array['NMT', 'ARC']::text[], '{"bank": 1, "summary": "[שם] מתקשה להתרכז ולהשתתף בלמידה, וזה מתבטא ב[איך זה נראה]. כרגע הכי חשוב לעזור ל[שם] להשתתף, לבקש עזרה ולהרגיש מצליח/ה. [מה כבר עוזר].", "goal_titles": ["השתתפות בפעילות לימודית", "בקשת עזרה בלמידה", "התמודדות עם תסכול"], "parts": {"avoid": "ממה להימנע – למידה", "signs": "אותות מוקדמים – למידה", "calm": "מה עוזר להירגע – למידה", "routine": "שגרה – למידה"}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, draft = true where public.mercury_library.content is null;
insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'goal', 'שמירה על הגוף שלי ושל אחרים', 'לכעוס בלי להכות, לבעוט, לנשוך או לזרוק', array['התנהגות מסכנת וגבולות', 'ויסות רגשי']::text[], 'התנהגות מסכנת וגבולות', array['ARC', 'NMT', 'ויסות חושי']::text[], '{"bank": 1, "review": 1, "scale": ["פוגע/ת פיזית כמה פעמים ביום", "פוגע/ת פעם ביום, נרגע/ת עם מבוגר", "עוצר/ת כשמבוגר מתקרב ומזכיר", "מחליף/ה מכה בפעולה אחרת עם תזכורת", "שומר/ת על הגוף לבד גם בכעס"], "avoid": "לא להגיב במגע כוחני או בצעקה; לא לרסן פיזית אלא לפי נוהל המרכז", "strengths": ["שליטה עצמית", "אחריות"], "skills": ["שמירה על הגוף"], "ages": {"2-5": {"targets": "מספר אירועי ההכאה או הנשיכה יורד מ-3 ביום ל-1 ביום, תוך חודש", "steps": ["כשהילד/ה מרים/ה יד ← עוצרים בעדינות את היד ואומרים: לא מכים. אפשר לרקוע ברגליים", "אחרי האירוע ← לא מרחיקים לזמן ארוך; חוזרים לקשר מהר"], "principles": "גבול ברור וקצר, וחזרה מהירה לקשר", "sentences": ["לא מכים. אפשר לכעוס", "בוא/י נרקע ברגליים חזק"], "seen": "מכה ונושך/ת כשכועס/ת או מתוסכל/ת", "needs": "דרך אחרת לפרוק כעס בגוף", "why": "בגיל הזה ביטוי גופי הוא נורמטיבי; הטראומה מעצימה אותו. מחליפים פעולה, לא מדכאים רגש", "why_staff": "לא מספיק להגיד לא להכות. צריך להראות מה כן לעשות עם הכעס", "method": "ARC – ויסות: ביטוי בטוח"}, "5-8": {"targets": "משתמש/ת בפעולה חלופית (כרית, קפיצות, לצאת לפינה) במקום להכות, ב-3 מתוך 5 פעמים בשבוע", "steps": ["כשמתחיל כעס ← מזכירים במילה אחת את הפעולה החלופית ומלווים", "אחרי שנרגע/ת ← שיחה קצרה: מה עזר? מה נעשה בפעם הבאה?"], "principles": "מכינים חלופות ברוגע, משתמשים בהן בכעס", "sentences": ["הידיים שלך חזקות. בוא/י נשתמש בהן על הכרית", "שמרת על הגוף, ראיתי"], "seen": "מכה ילדים ומבוגרים, זורק/ת חפצים", "needs": "חלופות גופניות ומבוגר רגוע", "why": "פעולה גופנית חלופית מאפשרת פריקה של עוררות בלי פגיעה", "why_staff": "כשיש לילד/ה מה לעשות עם הידיים, הוא/היא מכה פחות", "method": "ויסות חושי: פריקה גופנית בטוחה"}, "8-12": {"targets": "יום שלם בלי פגיעה פיזית ב-5 מתוך 7 ימים, תוך 3 חודשים", "steps": ["בונים יחד תוכנית בטיחות אישית: מה מרגיש לפני, מה עושים, למי פונים", "אחרי אירוע ← שיחת תיקון ואחריות, לא רק עונש"], "principles": "אחריות ותיקון, לא השפלה", "sentences": ["מה התוכנית שלך כשאת/ה מרגיש/ה שזה מגיע?", "איך אפשר לתקן עם מי שנפגע?"], "seen": "תוקפנות שמסלימה, פגיעה בחפצים ובאנשים", "needs": "תוכנית בטיחות ותחושה שאפשר לתקן", "why": "תוכנית בטיחות מגייסת חשיבה מראש; תיקון מחזק אחריות במקום בושה", "why_staff": "תוכנית שהילד/ה בנה/תה בעצמו/בעצמה עובדת יותר מאיומים", "method": "NMT: ויסות ואז חשיבה"}}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, draft = true where public.mercury_library.content is null;
insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'goal', 'גבולות הגוף ופרטיות', 'לשמור על הגוף שלי ועל הגוף של אחרים, ולכבד פרטיות', array['התנהגות מסכנת וגבולות', 'קשרים חברתיים']::text[], 'התנהגות מסכנת וגבולות', array['TF-CBT', 'ARC']::text[], '{"bank": 1, "review": 3, "scale": ["לא מבחין/ה בגבולות גוף בכלל", "עוצר/ת כשמבוגר מזכיר", "מכבד/ת כללי פרטיות עם תזכורת", "שואל/ת לפני מגע", "שומר/ת על גבולות ואומר/ת לא כשצריך"], "avoid": "לא להגיב בבהלה או בבושה; תגובה רגועה, ברורה, ודיווח לפי נוהל המרכז והמטפל/ת", "strengths": ["אחריות", "שליטה עצמית"], "skills": ["שמירה על הגוף"], "ages": {"2-5": {"targets": "מכבד/ת את כללי הגוף הפשוטים (שואלים לפני חיבוק, הגוף שלי שלי) עם תזכורת, ב-4 מתוך 5 פעמים", "steps": ["מלמדים במשחק ובספרים: הגוף שלי שלי, שואלים לפני שנוגעים", "כשיש מגע לא מתאים ← עוצרים ברוגע, מפנים לפעילות אחרת ומעדכנים את המטפל/ת"], "principles": "תגובה רגועה וברורה, בלי בושה, ועדכון המטפל/ת", "sentences": ["הגוף שלך שלך, והגוף שלו שלו", "שואלים לפני שמחבקים"], "seen": "סקרנות גופנית לא תואמת גיל או מגע לא מתאים", "needs": "כללים פשוטים ומבוגר רגוע", "why": "לימוד כללי גוף בגיל צעיר הוא מוגן ומפחית סיכון; תגובה רגועה מונעת בושה", "why_staff": "חשוב להגיב ברוגע, להפנות לפעילות אחרת ולעדכן את המטפל/ת. לא לבייש", "method": "TF-CBT: מיומנויות בטיחות גופנית"}, "5-8": {"targets": "שומר/ת על כללי פרטיות (שירותים, מקלחת, החלפת בגדים) עם תזכורת, ב-5 מתוך 7 ימים", "steps": ["כללי פרטיות ברורים ותלויים בתמונות ← מזכירים לפני מקלחת", "כשיש התנהגות לא מתאימה ← עוצרים ברוגע, לא חוקרים, מעדכנים את המטפל/ת לפי הנוהל"], "principles": "מבנה והשגחה, בלי שאלות חוקרות", "sentences": ["במקלחת כל אחד לבד", "הגוף שלך פרטי, וגם של כולם"], "seen": "חוסר הבחנה בפרטיות, משחק או מגע לא תואם גיל", "needs": "כללים, השגחה ומבוגר שלא נבהל", "why": "התנהגות מינית לא תואמת גיל היא לרוב סימן למצוקה ולחשיפה; מבנה והשגחה מגינים על כל הילדים", "why_staff": "לא חוקרים ולא מבהילים. עוצרים, מגינים, ומעדכנים את המטפל/ת", "method": "TF-CBT: בטיחות ופסיכו-חינוך"}, "8-12": {"targets": "מכבד/ת גבולות גוף ופרטיות של אחרים ואומר/ת לא כשמישהו לא מכבד את שלו/שלה, לאורך 3 חודשים", "steps": ["שיחות קבועות עם המטפל/ת על גוף, גבולות וקשרים בטוחים", "כשהילד/ה מספר/ת על משהו מדאיג ← מקשיבים, מרגיעים, לא מבטיחים סוד ומדווחים לפי הנוהל"], "principles": "הקשבה, הגנה ודיווח, תמיד יחד עם המטפל/ת", "sentences": ["טוב שסיפרת. אנחנו נשמור עליך", "מותר לך להגיד לא"], "seen": "גבולות לא ברורים בקשרים, חשיפה למצבי סיכון", "needs": "ידע, שפה ומבוגרים מגינים", "why": "בגיל הזה יש להוסיף חינוך לגבולות ולקשרים בטוחים כחלק ממניעת פגיעה חוזרת", "why_staff": "אם הילד/ה מספר/ת משהו מדאיג: מקשיבים, לא מבטיחים סוד, ומעדכנים מיד לפי הנוהל", "method": "TF-CBT: בטיחות אישית"}}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, draft = true where public.mercury_library.content is null;
insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'goal', 'שמירה על עצמי ברגעים קשים', 'כשרע לי, לבחור דרך שלא פוגעת בי, ולפנות למבוגר', array['התנהגות מסכנת וגבולות', 'ויסות רגשי', 'ביטחון ויציבות']::text[], 'התנהגות מסכנת וגבולות', array['TF-CBT', 'ARC']::text[], '{"bank": 1, "review": 1, "scale": ["פוגע/ת בעצמו/בעצמה ברגעי קושי", "פוגע/ת פחות, עם מבוגר קרוב", "פונה למבוגר כשמרגיש/ה שזה מתקרב", "משתמש/ת בכלי במקום לפגוע", "שומר/ת על עצמו/עצמה ומספר/ת אחר כך"], "avoid": "לא להתעלם ולא להבהיל; כל פגיעה עצמית או דיבור עליה מועברים מיד למטפל/ת לפי נוהל המרכז", "strengths": ["אומץ", "בקשת עזרה"], "skills": ["בקשת עזרה", "הירגעות בעזרת כלי"], "ages": {"2-5": {"targets": "מספר הפעמים שהילד/ה מכה את הראש או את עצמו/עצמה ברגעי בכי יורד בחצי, תוך חודש", "steps": ["כשהילד/ה מתחיל/ה לפגוע בעצמו/בעצמה ← מגינים בעדינות (כרית, יד), מרגיעים בקול רך", "מתעדים מתי זה קורה ומעדכנים את המטפל/ת"], "principles": "הגנה עדינה ורגיעה; מתעדים ומעדכנים", "sentences": ["אני שומר/ת עליך", "קשה לך. אני פה"], "seen": "מכה את הראש, נושך/ת את עצמו/עצמה", "needs": "הגנה ומבוגר מווסת", "why": "פגיעה עצמית בגיל צעיר היא לרוב ביטוי למצוקה ולקושי בוויסות; ויסות משותף והגנה הם הצעד הראשון", "why_staff": "מגינים עליו/עליה בעדינות, מרגיעים, ותמיד מעדכנים את המטפל/ת", "method": "ARC – ויסות משותף"}, "5-8": {"targets": "פונה למבוגר או משתמש/ת בכלי הרגעה במקום לפגוע בעצמו/בעצמה, ב-3 מתוך 4 פעמים", "steps": ["תוכנית בטיחות קצרה עם המטפל/ת ← הצוות מכיר אותה", "כשמזהים סימן מוקדם ← מתקרבים, מציעים כלי ונשארים"], "principles": "נוכחות, כלי, דיווח", "sentences": ["אני רואה שקשה לך. אני נשאר/ת", "בוא/י ננסה את הכלי שלך"], "seen": "מכה את עצמו/עצמה, שורט/ת, אומר/ת משפטים קשים על עצמו/עצמה", "needs": "תוכנית בטיחות ומבוגרים שמכירים אותה", "why": "תוכנית בטיחות אישית מפחיתה התנהגות פוגענית ומחזקת פנייה לעזרה", "why_staff": "כל משפט קשה או פגיעה עוברים למטפל/ת מיד. לא נשארים עם זה לבד", "method": "TF-CBT: תוכנית בטיחות"}, "8-12": {"targets": "משתמש/ת בתוכנית הבטיחות (כלי, מבוגר, מקום) ברגעים קשים ומספר/ת אחר כך, לאורך 3 חודשים", "steps": ["הצוות מכיר את תוכנית הבטיחות ושומר עליה בסוד מקצועי, לא מול ילדים", "כשיש סימני מצוקה ← שואלים ישירות ובעדינות אם עולות מחשבות לפגוע, ומעדכנים מיד"], "principles": "שאלה ישירה ועדינה מגינה; דיווח מיידי לפי הנוהל", "sentences": ["אני רואה שקשה לך. עולות לך מחשבות לפגוע בעצמך?", "טוב שאמרת. לא תהיה/תהיי עם זה לבד"], "seen": "שריטות, הסתגרות, דיבור על רצון להיעלם", "needs": "מבוגרים שלא נבהלים, שואלים ומגינים", "why": "שאלה ישירה על מחשבות פגיעה אינה מגבירה סיכון; היא מאפשרת הגנה וטיפול", "why_staff": "מותר ורצוי לשאול. כל תשובה מדאיגה מועברת מיד למטפל/ת ולאחראי/ת על המשמרת", "method": "TF-CBT: בטיחות והתמודדות"}}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, draft = true where public.mercury_library.content is null;
insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'goal', 'קבלת גבול ממבוגר', 'לשמוע לא ממבוגר ולהמשיך בלי פיצוץ', array['התנהגות מסכנת וגבולות', 'היקשרות וקשר עם מבוגר']::text[], 'התנהגות מסכנת וגבולות', array['DDP/PACE', 'ARC']::text[], '{"bank": 1, "review": 3, "scale": ["כל גבול מוביל להתפרצות", "מתפרץ/ת ונרגע/ת אחרי זמן", "מתווכח/ת ומקבל/ת", "מקבל/ת עם אכזבה במילים", "מקבל/ת ומציע/ה חלופה"], "avoid": "לא להציב גבול בצעקה, בלעג או מול כולם", "strengths": ["שליטה עצמית", "גמישות"], "skills": [], "ages": {"2-5": {"targets": "מקבל/ת לא ממבוגר ועובר/ת לחלופה שמוצעת, ב-3 מתוך 5 פעמים", "steps": ["מציבים גבול במשפט קצר ← מציעים מיד חלופה", "כשהילד/ה בוכה ← מכירים ברגש ומחזיקים את הגבול"], "principles": "גבול קצר, חלופה מיידית, הכרה ברגש", "sentences": ["לא טפסים על השולחן. אפשר לטפס על הכיסא הגבוה בחצר", "את/ה כועס/ת. זה בסדר"], "seen": "נזרק/ת לרצפה, מכה כשאומרים לא", "needs": "גבול עם חלופה ומבוגר רגוע", "why": "גבול עקבי וחם יוצר ביטחון; חלופה מאפשרת שליטה", "why_staff": "כשיש חלופה, הלא קל יותר", "method": "ARC – ויסות: גבול עם חלופה"}, "5-8": {"targets": "מקבל/ת גבול ומביע/ה אכזבה במילים (במקום התפרצות), ב-3 מתוך 5 פעמים בשבוע", "steps": ["מסבירים בקצרה את הסיבה לגבול ← בלי להתווכח", "כשמבטא/ת אכזבה במילים ← משבחים את זה"], "principles": "מסבירים פעם אחת, לא מתווכחים", "sentences": ["אני רואה שאת/ה מאוכזב/ת, והתשובה עדיין לא", "אמרת את זה במילים, כל הכבוד"], "seen": "מתווכח/ת ללא סוף, מתפרץ/ת", "needs": "גבול עקבי וחם", "why": "עקביות בגבולות מפחיתה מבחנים חוזרים; הכרה ברגש מפחיתה הסלמה", "why_staff": "אם מתווכחים, הילד/ה לומד/ת שאפשר לשנות את הגבול בכוח", "method": "DDP/PACE: קבלה של רגש, החזקת גבול"}, "8-12": {"targets": "מקבל/ת גבול ומציע/ה חלופה או משא ומתן מכבד, ב-3 מתוך 4 פעמים", "steps": ["מבחינים בין גבולות קבועים (בטיחות) לגבולות שאפשר לדון בהם", "כשמבקש/ת לדון ← מקשיבים, ומחליטים ברוגע"], "principles": "שקיפות: מה קבוע ומה אפשר לדון", "sentences": ["זה גבול של בטיחות, הוא לא משתנה", "על זה אפשר לדבר. מה את/ה מציע/ה?"], "seen": "מאבקי כוח, מבחנים חוזרים של גבולות", "needs": "כבוד וגבולות ברורים", "why": "שקיפות בהבחנה בין גבולות מפחיתה מאבקי כוח ומכבדת סוכנות", "why_staff": "כשברור מה אפשר לדון ומה לא, יש פחות מאבקים", "method": "DDP/PACE: גבולות בתוך קשר"}}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, draft = true where public.mercury_library.content is null;
insert into public.mercury_library (scope, kind, title, description, themes, category, content, draft) values ('mercury', 'avoid', 'ממה להימנע – גבולות', 'לא להציב גבול בלעג או מול כולם. לא לאיים באיומים שלא יתקיימו. לא להבהיל או לבייש על התנהגות גופנית.', array['התנהגות מסכנת וגבולות']::text[], 'התנהגות מסכנת וגבולות', '{"bank": 1, "ages": {"2-5": "לא להגיב במגע כוחני. לא לצעוק. לא להרחיק לזמן ארוך אחרי אירוע.", "5-8": "לא להציב גבול בלעג או מול כולם. לא לאיים באיומים שלא יתקיימו. לא להבהיל או לבייש על התנהגות גופנית.", "8-12": "לא להיכנס למאבק כוח מול הקבוצה. לא לחקור בעצמנו על אירועים רגישים. לא להבטיח סוד כשמדובר בסכנה."}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, draft = true where public.mercury_library.content is null;
insert into public.mercury_library (scope, kind, title, description, themes, category, content, draft) values ('mercury', 'signs', 'אותות מוקדמים – גבולות', 'התגרות, קללות, דחיפות קלות, בדיקת המבוגר.', array['התנהגות מסכנת וגבולות']::text[], 'התנהגות מסכנת וגבולות', '{"bank": 1, "ages": {"2-5": "ידיים מתהדקות, צרחות, ריצה בחדר, זריקת חפצים.", "5-8": "התגרות, קללות, דחיפות קלות, בדיקת המבוגר.", "8-12": "שקט מאיים או התרסה, קללות, הליכה לכיוון הדלת, סימני פגיעה או הסתגרות."}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, draft = true where public.mercury_library.content is null;
insert into public.mercury_library (scope, kind, title, description, themes, category, content, draft) values ('mercury', 'calm', 'מה עוזר להירגע – גבולות', 'פעולה חלופית (כרית, קפיצות), יציאה לפינה עם מבוגר. משפט: הידיים שלך חזקות, בוא/י נשתמש בהן על הכרית.', array['התנהגות מסכנת וגבולות']::text[], 'התנהגות מסכנת וגבולות', '{"bank": 1, "ages": {"2-5": "מבוגר רגוע ונמוך, רקיעה ברגליים, כרית, חיבוק אם רוצה. משפט: לא מכים, אפשר לכעוס. אני פה.", "5-8": "פעולה חלופית (כרית, קפיצות), יציאה לפינה עם מבוגר. משפט: הידיים שלך חזקות, בוא/י נשתמש בהן על הכרית.", "8-12": "מרחב, פחות מילים, מבוגר אחד, תוכנית הבטיחות. משפט: אני פה. כשתהיה/תהיי מוכן/ה, נדבר."}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, draft = true where public.mercury_library.content is null;
insert into public.mercury_library (scope, kind, title, description, themes, category, content, draft) values ('mercury', 'routine', 'שגרה – גבולות', 'כללי פרטיות תלויים. השגחה במקלחת ובשינה. שיחה יומית קצרה על איך היה.', array['התנהגות מסכנת וגבולות']::text[], 'התנהגות מסכנת וגבולות', '{"bank": 1, "ages": {"2-5": "כללים מעטים ופשוטים בתמונות. השגחה צמודה במעברים ובמקלחת.", "5-8": "כללי פרטיות תלויים. השגחה במקלחת ובשינה. שיחה יומית קצרה על איך היה.", "8-12": "תוכנית בטיחות שהצוות מכיר. מבוגר קבוע לשיחה. השגחה במצבים מועדים."}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, draft = true where public.mercury_library.content is null;
insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'plan', 'תכנית: התנהגות מסכנת וגבולות', '[שם] מגיב/ה ברגעי קושי בגוף, וזה מתבטא ב[איך זה נראה]. כרגע הכי חשוב לשמור על הבטיחות של [שם] ושל כולם, ולתת דרכים אחרות לכעס. הכל לפי נוהל המרכז ויחד עם המטפל/ת. [מה כבר עוזר].', array['התנהגות מסכנת וגבולות']::text[], 'התנהגות מסכנת וגבולות', array['ARC', 'TF-CBT']::text[], '{"bank": 1, "summary": "[שם] מגיב/ה ברגעי קושי בגוף, וזה מתבטא ב[איך זה נראה]. כרגע הכי חשוב לשמור על הבטיחות של [שם] ושל כולם, ולתת דרכים אחרות לכעס. הכל לפי נוהל המרכז ויחד עם המטפל/ת. [מה כבר עוזר].", "goal_titles": ["שמירה על הגוף שלי ושל אחרים", "קבלת גבול ממבוגר", "שימוש בכלי הרגעה"], "parts": {"avoid": "ממה להימנע – גבולות", "signs": "אותות מוקדמים – גבולות", "calm": "מה עוזר להירגע – גבולות", "routine": "שגרה – גבולות"}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, draft = true where public.mercury_library.content is null;
insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'goal', 'שגרת שינה רגועה', 'להירדם ולישון בתחושת ביטחון, בעזרת טקס קבוע', array['שינה ואכילה', 'ביטחון ויציבות']::text[], 'שינה ואכילה', array['NMT', 'ויסות חושי', 'ARC']::text[], '{"bank": 1, "review": 3, "scale": ["לא נרדם/ת שעות, יוצא/ת שוב ושוב", "נרדם/ת רק עם מבוגר צמוד זמן רב", "נרדם/ת עם טקס ומבוגר קרוב", "נרדם/ת עם טקס ומבוגר בחדר", "נרדם/ת לבד אחרי הטקס"], "avoid": "לא לאיים או להעניש לפני השינה; לא לכבות אור פתאום", "strengths": ["סבלנות", "שליטה עצמית"], "skills": [], "ages": {"2-5": {"targets": "נרדם/ת תוך 30 דקות אחרי טקס שינה קבוע, ב-4 מתוך 7 לילות", "steps": ["טקס קבוע: מקלחת, פיג׳מה, סיפור, שיר, חפץ מעבר ← באותו סדר כל ערב", "המבוגר יושב ליד המיטה ומתרחק בהדרגה במשך שבועות"], "principles": "אותו טקס, אותו סדר, נוכחות שמתרחקת לאט", "sentences": ["עכשיו הסיפור ואז השיר", "אני פה ליד, את/ה בטוח/ה"], "seen": "מתקשה להירדם, בוכה בלילה, יוצא/ת מהמיטה", "needs": "טקס צפוי ונוכחות מבוגר", "why": "שינה דורשת תחושת ביטחון; בטראומה מערכת הדריכות פעילה בלילה. טקס קצבי וצפוי מווסת", "why_staff": "אותו טקס בכל ערב, גם כשמשמרת מתחלפת, עוזר לגוף להירגע", "method": "NMT: קצב וחזרתיות"}, "5-8": {"targets": "נשאר/ת במיטה ונרדם/ת תוך 30 דקות אחרי הטקס, ב-5 מתוך 7 לילות", "steps": ["לוח טקס שינה בתמונות ← הילד/ה מסמן/ת כל שלב", "מנורת לילה ושמיכה כבדה אם עוזרות; מבוגר עובר כל 10 דקות"], "principles": "ביקורים קבועים במקום להישאר צמוד", "sentences": ["אני אבוא לבדוק עוד 10 דקות", "השמיכה הכבדה פה אם רוצה"], "seen": "מבקש/ת עוד ועוד, קם/ה, מפחד/ת בחושך", "needs": "ודאות שמבוגר זמין גם בלילה", "why": "בדיקות צפויות מפחיתות חרדת נטישה ומאפשרות הירדמות עצמאית בהדרגה", "why_staff": "כשהילד/ה יודע/ת שנבוא לבדוק, קל לו/לה להישאר במיטה", "method": "ויסות חושי: שמיכה כבדה ותאורה רכה"}, "8-12": {"targets": "מנהל/ת שגרת ערב (מסכים כבויים, הכנה, קריאה) ונרדם/ת בזמן, ב-5 מתוך 7 לילות, תוך 3 חודשים", "steps": ["מסכמים יחד שעת כיבוי מסכים ושגרה שהילד/ה בחר/ה", "שיחת ערב קצרה: מה עובר עליך? ← עוזר לפרוק לפני השינה"], "principles": "שגרה שהילד/ה שותף/ה לה", "sentences": ["יש משהו שמטריד אותך לפני השינה?", "מה יעזור לך להירדם הלילה?"], "seen": "נשאר/ת ער/ה, מחשבות ודאגות בלילה", "needs": "פריקה לפני שינה ושגרה אישית", "why": "מחשבות טורדניות בלילה שכיחות בטראומה; שיחת ערב ושגרה מפחיתות עוררות", "why_staff": "שיחה קצרה לפני השינה עוזרת להירדם", "method": "ARC – ויסות: שגרות שינה"}}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, draft = true where public.mercury_library.content is null;
insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'goal', 'התמודדות עם פחדי לילה', 'לחזור להירדם אחרי סיוט או פחד בלילה', array['שינה ואכילה', 'ביטחון ויציבות', 'ויסות רגשי']::text[], 'שינה ואכילה', array['TF-CBT', 'ARC']::text[], '{"bank": 1, "review": 3, "scale": ["מתעורר/ת בבהלה ולא נרגע/ת שעות", "נרגע/ת רק עם מבוגר צמוד", "נרגע/ת עם מבוגר וכלי", "קורא/ת למבוגר ונרגע/ת מהר", "משתמש/ת בכלי לבד וחוזר/ת לישון"], "avoid": "לא לשאול על פרטי הסיוט באמצע הלילה; מרגיעים ומחזירים לשינה", "strengths": ["אומץ", "בקשת עזרה"], "skills": ["הירגעות בעזרת כלי"], "ages": {"2-5": {"targets": "חוזר/ת להירדם תוך 20 דקות עם מבוגר אחרי התעוררות בבהלה, ב-3 מתוך 5 לילות", "steps": ["כשהילד/ה מתעורר/ת בבכי ← ניגשים מהר, אור עמום, קול רך, חפץ מעבר", "נשארים עד שנרגע/ת, בלי שאלות"], "principles": "מרגיעים ולא שואלים", "sentences": ["זה היה חלום. את/ה פה, בטוח/ה", "אני כאן עד שתירדם/תירדמי"], "seen": "צרחות בלילה, בלבול בהתעוררות", "needs": "מבוגר מרגיע מהיר", "why": "התעוררות בבהלה דורשת ויסות מהיר; שאלות מגבירות עוררות", "why_staff": "בלילה רק מרגיעים. על החלום, אם בכלל, מדברים ביום עם המטפל/ת", "method": "ARC – ויסות משותף"}, "5-8": {"targets": "קורא/ת למבוגר או משתמש/ת בכלי (פנס, בובה, נשימה) אחרי סיוט וחוזר/ת לישון, ב-3 מתוך 5 לילות", "steps": ["מכינים עם המטפל/ת ערכת לילה: פנס, בובה שומרת, כרטיס נשימה", "אחרי סיוט ← עוזרים להשתמש בערכה ומחזירים לשינה"], "principles": "ערכה מוכנה מראש", "sentences": ["בוא/י נדליק את הפנס ונבדוק יחד", "הבובה שומרת עליך, ואני גם"], "seen": "מפחד/ת להירדם, נכנס/ת למיטה של אחרים", "needs": "כלים לשליטה בפחד הלילי", "why": "כלים מוחשיים מעניקים תחושת שליטה ומפחיתים הימנעות משינה", "why_staff": "ערכת לילה מוכנה עוזרת לחזור לישון מהר", "method": "TF-CBT: מיומנויות התמודדות"}, "8-12": {"targets": "חוזר/ת לישון לבד אחרי סיוט בעזרת כלי, ומספר/ת למבוגר בבוקר אם רוצה, ב-3 מתוך 4 לילות", "steps": ["בבוקר ← מציעים לספר, לא לוחצים", "מעבירים למטפל/ת כשיש סיוטים חוזרים"], "principles": "בחירה לספר, מעקב ועדכון", "sentences": ["רוצה לספר על הלילה?", "סיוטים קורים כשהגוף עוד זוכר. אפשר לעבוד על זה עם המטפל/ת"], "seen": "סיוטים חוזרים, עייפות ביום", "needs": "כלים ומבוגר שמבין", "why": "סיוטים חוזרים הם תסמין טראומה שכיח; ניתן לעבוד עליהם בטיפול ממוקד", "why_staff": "סיוטים חוזרים מעדכנים את המטפל/ת. יש לזה טיפול", "method": "TF-CBT: עבודה על סיוטים"}}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, draft = true where public.mercury_library.content is null;
insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'goal', 'ארוחה רגועה ומשותפת', 'לשבת לארוחה עם כולם ולאכול ברוגע', array['שינה ואכילה', 'קשרים חברתיים']::text[], 'שינה ואכילה', array['ויסות חושי', 'ARC']::text[], '{"bank": 1, "review": 3, "scale": ["לא יושב/ת לארוחה בכלל", "יושב/ת דקות ספורות", "יושב/ת חצי ארוחה עם עידוד", "יושב/ת רוב הארוחה", "יושב/ת ומשתתף/ת בשיחה"], "avoid": "לא להכריח לאכול או לסיים; לא להשתמש באוכל כפרס או כעונש", "strengths": ["סבלנות", "שיתוף"], "skills": [], "ages": {"2-5": {"targets": "יושב/ת בארוחה 10 דקות ליד מבוגר, ב-5 מתוך 7 ימים", "steps": ["מקום קבוע ליד מבוגר מוכר ← אותו כיסא, אותה צלחת", "מנה קטנה ואפשרות לבקש עוד"], "principles": "מקום קבוע ומנות קטנות", "sentences": ["פה המקום שלך", "רוצה עוד קצת?"], "seen": "קם/ה, משחק/ת באוכל, בוכה בארוחה", "needs": "צפיות ונוכחות מבוגר", "why": "ארוחה משותפת היא הזדמנות לוויסות ולקשר; עומס חושי בארוחה גבוה", "why_staff": "מקום קבוע ליד מבוגר מוכר עוזר לשבת", "method": "ויסות חושי: הפחתת עומס בארוחה"}, "5-8": {"targets": "יושב/ת לאורך רוב הארוחה ומשתתף/ת בשיחה קצרה, ב-5 מתוך 7 ימים", "steps": ["מקום שקט בקצה השולחן אם רעש מציף", "שאלה אחת קלה לשיחה בכל ארוחה"], "principles": "התאמה חושית והשתתפות קלה", "sentences": ["מה היה הכי כיף היום?", "אם רועש, אפשר לשבת בקצה"], "seen": "מוצף/ת מרעש, ממהר/ת לסיים או מתווכח/ת", "needs": "סביבה פחות מציפה", "why": "התאמה חושית מגבירה השתתפות; ארוחה רגועה מחזקת תחושת משפחתיות", "why_staff": "לפעמים מקום שקט יותר בשולחן עושה את כל ההבדל", "method": "ARC – ויסות: התאמות סביבה"}, "8-12": {"targets": "משתתף/ת בארוחה עד הסוף ובעזרה קטנה (עריכה או פינוי), ב-5 מתוך 7 ימים", "steps": ["תפקיד קבוע בארוחה ← עורך/ת שולחן או מחלק/ת", "שיחה קלה ולא חוקרת"], "principles": "תפקיד והשתייכות", "sentences": ["תודה שערכת את השולחן", "מה דעתך על האוכל היום?"], "seen": "מתנתק/ת, יוצא/ת מוקדם", "needs": "תפקיד ושייכות", "why": "תפקיד בארוחה מחזק שייכות ותחושת ערך", "why_staff": "תפקיד קטן בארוחה גורם להרגיש חלק מהבית", "method": "ARC – מסוגלות: תפקיד ושייכות"}}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, draft = true where public.mercury_library.content is null;
insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'goal', 'ביטחון סביב אוכל', 'לסמוך שיהיה אוכל, בלי להחביא או לאכול בלי שובע', array['שינה ואכילה', 'ביטחון ויציבות']::text[], 'שינה ואכילה', array['ARC', 'NMT']::text[], '{"bank": 1, "review": 3, "scale": ["מחביא/ה אוכל ואוכל/ת בלי שובע", "מחביא/ה פחות עם תזכורת שיש עוד", "סומך/ת שיש עוד כשרואה את המזווה", "אוכל/ת ומפסיק/ה בשובע רוב הזמן", "רגוע/ה סביב אוכל"], "avoid": "לא להעניש על החבאת אוכל; לא לאסור גישה כעונש", "strengths": ["סבלנות", "כנות"], "skills": [], "ages": {"2-5": {"targets": "מפסיק/ה לאכול כשמבוגר שואל אם שבע/ה ומזכיר שיהיה עוד, ב-3 מתוך 5 ארוחות", "steps": ["מראים לילד/ה שיש עוד ← קופסת חטיף קבועה שתמיד מלאה", "שואלים בעדינות: הבטן מלאה?"], "principles": "שפע צפוי במקום מחסור", "sentences": ["תמיד יש עוד אוכל פה", "הבטן מלאה או רוצה עוד?"], "seen": "אוכל/ת מהר מאוד, בוכה כשמפנים צלחת", "needs": "ודאות שיהיה אוכל", "why": "התנהגויות סביב אוכל הן לרוב תגובה לחוויית מחסור או הזנחה; ודאות מתקנת", "why_staff": "ילד/ה שהיה/הייתה רעב/ה בעבר צריך/ה לראות שתמיד יש עוד", "method": "ARC – ביטחון: צרכים בסיסיים"}, "5-8": {"targets": "מספר הפעמים שנמצא אוכל מוחבא יורד בחצי, תוך חודשיים", "steps": ["מגירה אישית עם חטיף קבוע ← הילד/ה יודע/ת שהיא שלו/שלה", "כשנמצא אוכל מוחבא ← לא מענישים; מזכירים בשקט שיש מגירה"], "principles": "בלי עונש, עם ודאות", "sentences": ["יש לך מגירה עם חטיף, תמיד", "את/ה לא צריך/ה להחביא, יש מספיק"], "seen": "מחביא/ה אוכל בחדר, לוקח/ת מאחרים", "needs": "תחושה שהאוכל שלו/שלה מובטח", "why": "החבאת אוכל היא אסטרטגיית הישרדות; ודאות ושליטה מפחיתות אותה", "why_staff": "החבאת אוכל היא לא גניבה. זה פחד שלא יהיה", "method": "NMT: ויסות מערכת ההישרדות"}, "8-12": {"targets": "מזהה רעב ושובע ואוכל/ת בהתאם, ב-5 מתוך 7 ימים, תוך 3 חודשים", "steps": ["שיחה פרטית עם המטפל/ת על אוכל ותחושות", "גישה מוסכמת לחטיפים בשעות קבועות"], "principles": "שליטה וכבוד", "sentences": ["מה הגוף אומר, רעב או משהו אחר?", "יש חטיף בשעה ארבע, כמו תמיד"], "seen": "אכילה רגשית, הסתרה", "needs": "כלים לזיהוי צרכים וגישה מוסכמת", "why": "הבחנה בין רעב פיזי לרגשי מחזקת ויסות", "why_staff": "לפעמים אוכלים כשעצובים. אפשר לשאול בעדינות מה הגוף צריך", "method": "ARC – ויסות: זיהוי צרכים"}}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, draft = true where public.mercury_library.content is null;
insert into public.mercury_library (scope, kind, title, description, themes, category, content, draft) values ('mercury', 'avoid', 'ממה להימנע – שינה ואכילה', 'לא לאיים לפני השינה. לא להעניש על החבאת אוכל. לא לשאול על סיוט באמצע הלילה.', array['שינה ואכילה']::text[], 'שינה ואכילה', '{"bank": 1, "ages": {"2-5": "לא לכבות אור פתאום. לא להכריח לאכול. לא להשתמש באוכל כפרס או כעונש.", "5-8": "לא לאיים לפני השינה. לא להעניש על החבאת אוכל. לא לשאול על סיוט באמצע הלילה.", "8-12": "לא להעיר על משקל או על כמות. לא לקחת מסכים בכוח לפני השינה בלי הסכם. לא לחקור על הלילה."}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, draft = true where public.mercury_library.content is null;
insert into public.mercury_library (scope, kind, title, description, themes, category, content, draft) values ('mercury', 'signs', 'אותות מוקדמים – שינה ואכילה', 'מבקש/ת עוד ועוד בערב, פוחד/ת מהחושך, מחביא/ה אוכל.', array['שינה ואכילה']::text[], 'שינה ואכילה', '{"bank": 1, "ages": {"2-5": "עייפות ובכי לפני השינה, נצמד/ת, אוכל/ת מהר או מסרב/ת.", "5-8": "מבקש/ת עוד ועוד בערב, פוחד/ת מהחושך, מחביא/ה אוכל.", "8-12": "ער/ה עד מאוחר, עייפות ביום, אכילה רגשית או הימנעות מאוכל."}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, draft = true where public.mercury_library.content is null;
insert into public.mercury_library (scope, kind, title, description, themes, category, content, draft) values ('mercury', 'calm', 'מה עוזר להירגע – שינה ואכילה', 'מנורת לילה, שמיכה כבדה, ביקורים קבועים, ערכת לילה. משפט: אני אבוא לבדוק עוד 10 דקות.', array['שינה ואכילה']::text[], 'שינה ואכילה', '{"bank": 1, "ages": {"2-5": "טקס שינה קבוע, שיר, חפץ מעבר, אור עמום. משפט: אני פה ליד, את/ה בטוח/ה.", "5-8": "מנורת לילה, שמיכה כבדה, ביקורים קבועים, ערכת לילה. משפט: אני אבוא לבדוק עוד 10 דקות.", "8-12": "שיחת ערב קצרה, קריאה, מוזיקה שקטה. משפט: יש משהו שמטריד אותך לפני השינה?"}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, draft = true where public.mercury_library.content is null;
insert into public.mercury_library (scope, kind, title, description, themes, category, content, draft) values ('mercury', 'routine', 'שגרה – שינה ואכילה', 'לוח טקס שינה. ביקורים כל 10 דקות. מגירת חטיף אישית.', array['שינה ואכילה']::text[], 'שינה ואכילה', '{"bank": 1, "ages": {"2-5": "אותו טקס שינה באותה שעה. מקום קבוע בארוחה. קופסת חטיף שתמיד מלאה.", "5-8": "לוח טקס שינה. ביקורים כל 10 דקות. מגירת חטיף אישית.", "8-12": "שעת כיבוי מסכים מוסכמת. תפקיד בארוחה. חטיף בשעה קבועה."}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, draft = true where public.mercury_library.content is null;
insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'plan', 'תכנית: שינה ואכילה', '[שם] מתקשה בשינה או סביב אוכל, וזה מתבטא ב[איך זה נראה]. כרגע הכי חשוב לתת ל[שם] ערב צפוי, לילה בטוח ותחושה שתמיד יש מספיק. [מה כבר עוזר].', array['שינה ואכילה']::text[], 'שינה ואכילה', array['NMT', 'ARC']::text[], '{"bank": 1, "summary": "[שם] מתקשה בשינה או סביב אוכל, וזה מתבטא ב[איך זה נראה]. כרגע הכי חשוב לתת ל[שם] ערב צפוי, לילה בטוח ותחושה שתמיד יש מספיק. [מה כבר עוזר].", "goal_titles": ["שגרת שינה רגועה", "ביטחון סביב אוכל", "תחושת ביטחון במרחב"], "parts": {"avoid": "ממה להימנע – שינה ואכילה", "signs": "אותות מוקדמים – שינה ואכילה", "calm": "מה עוזר להירגע – שינה ואכילה", "routine": "שגרה – שינה ואכילה"}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, draft = true where public.mercury_library.content is null;
insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'goal', 'ביטוי געגוע למשפחה', 'להגיד שמתגעגעים, ולמצוא דרך להרגיש קרוב/ה', array['אובדן ופרידה', 'ויסות רגשי']::text[], 'אובדן ופרידה', array['DDP/PACE', 'TF-CBT']::text[], '{"bank": 1, "review": 3, "scale": ["הגעגוע יוצא רק בהתפרצות או בהסתגרות", "בוכה ולא אומר/ת למה", "אומר/ת שמתגעגע/ת כשנשאל/ת", "אומר/ת ביוזמתו/ביוזמתה", "אומר/ת ובוחר/ת דרך להרגיש קרוב/ה"], "avoid": "לא להבטיח מפגשים או חזרה הביתה כשזה לא ידוע; לא לדבר רע על ההורים", "strengths": ["כנות", "אומץ"], "skills": ["מציאת מילים ברגע של קושי"], "ages": {"2-5": {"targets": "מראה או אומר/ת שמתגעגע/ת (מצביע/ה על תמונה, אומר/ת אמא) ומקבל/ת נחמה, ב-3 מתוך 5 פעמים", "steps": ["כשהילד/ה בוכה ואומר/ת אמא ← משקפים: את/ה מתגעגע/ת לאמא, ומחבקים אם רוצה", "תמונה של המשפחה ליד המיטה, אם זה אושר עם המטפל/ת"], "principles": "מקבלים את הגעגוע, לא מסיחים ממנו", "sentences": ["את/ה מתגעגע/ת לאמא", "מותר להתגעגע"], "seen": "בוכה בערב, מחפש/ת את ההורים", "needs": "רשות להתגעגע ומבוגר שמנחם", "why": "געגוע הוא ביטוי בריא להיקשרות; הכרה בו מפחיתה ביטוי התנהגותי", "why_staff": "כשמותר להתגעגע, הגעגוע פחות מתפוצץ", "method": "DDP/PACE: אמפתיה"}, "5-8": {"targets": "אומר/ת במילים שמתגעגע/ת ובוחר/ת דרך להרגיש קרוב/ה (ציור, מכתב, תמונה), לפחות פעם בשבוע", "steps": ["כשעולה געגוע ← מציעים: רוצה לצייר להם? לכתוב?", "שומרים את הציורים בקופסה מיוחדת"], "principles": "נותנים לגעגוע מקום ופעולה", "sentences": ["רוצה לצייר משהו לאמא?", "הגעגוע אומר שאת/ה אוהב/ת אותם"], "seen": "מתפרץ/ת לפני או אחרי שיחות טלפון", "needs": "דרך לבטא ולשמור על הקשר", "why": "פעולות סמליות של קשר מאפשרות ויסות של רגשות אובדן", "why_staff": "ציור או מכתב להורים נותן לגעגוע מקום", "method": "TF-CBT: הבעה רגשית"}, "8-12": {"targets": "מדבר/ת על הגעגוע ועל הרגשות המעורבים כלפי המשפחה עם מבוגר או מטפל/ת, לפחות פעם בשבוע", "steps": ["מקשיבים בלי לשפוט את המשפחה", "מאפשרים רגשות מעורבים: אהבה וכעס יחד"], "principles": "כבוד למשפחה ולרגשות מעורבים", "sentences": ["אפשר להתגעגע וגם לכעוס", "מה הכי חסר לך?"], "seen": "מכחיש/ה געגוע, אדישות מופגנת", "needs": "רשות לרגשות מעורבים", "why": "רגשות אמביוולנטיים כלפי ההורים שכיחים; קבלתם מפחיתה קונפליקט נאמנויות", "why_staff": "לא צריך לבחור צד. מותר לילד/ה לאהוב ולכעוס על המשפחה", "method": "DDP/PACE: קבלה"}}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, draft = true where public.mercury_library.content is null;
insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'goal', 'התמודדות עם מפגשים ושיחות עם המשפחה', 'להתכונן למפגש או לשיחה עם המשפחה, ולחזור ממנו בשלום', array['אובדן ופרידה', 'מעברים ושגרה']::text[], 'אובדן ופרידה', array['ARC', 'TF-CBT']::text[], '{"bank": 1, "review": 3, "scale": ["מתפרק/ת לפני ואחרי כל מפגש", "מתפרץ/ת אחרי ונרגע/ת לאט", "נרגע/ת אחרי עם טקס חזרה", "מספר/ת על המפגש ונרגע/ת", "מתכונן/ת ומעבד/ת עם מבוגר"], "avoid": "לא לשאול שאלות חוקרות על המפגש; לא להבטיח מפגש שלא בטוח", "strengths": ["אומץ", "גמישות"], "skills": [], "ages": {"2-5": {"targets": "חוזר/ת ממפגש ונרגע/ת תוך שעה בעזרת טקס חזרה קבוע, ב-3 מתוך 4 מפגשים", "steps": ["לפני ← אומרים מתי המפגש ומי יחזיר אותו/אותה", "אחרי ← טקס חזרה: חיבוק, שתייה, משחק שקט"], "principles": "ניבוי לפני, טקס אחרי", "sentences": ["היום פוגשים את אמא, ואחר כך חוזרים לפה", "ברוך/ה השב/ה. בוא/י נשתה ונשחק"], "seen": "בוכה או משתולל/ת אחרי ביקור", "needs": "מעבר חם ממפגש לשגרה", "why": "מפגשים מעוררים רגשות עזים; טקס חזרה מספק ויסות ומעבר", "why_staff": "אחרי מפגש לא שואלים, פשוט עוזרים לחזור", "method": "ARC – ויסות: טקסי מעבר"}, "5-8": {"targets": "חוזר/ת למשחק או לשגרה תוך שעה אחרי מפגש או שיחה, ב-3 מתוך 4 פעמים", "steps": ["לפני ← מכינים מה עושים אחרי (פעילות אהובה)", "אחרי ← מציעים לספר, מקבלים אם לא רוצה, ומעדכנים את המטפל/ת"], "principles": "מכינים את האחרי מראש", "sentences": ["אחרי השיחה נשחק בכדור, כמו שתכננו", "רוצה לספר איך היה? לא חייבים"], "seen": "שינויים בהתנהגות סביב מפגשים", "needs": "תכנון וקבלה", "why": "תכנון מקדים מפחית חרדת ציפייה וממתן תגובות אחרי", "why_staff": "כשיודעים מה עושים אחרי המפגש, קל יותר לחזור", "method": "ARC – ויסות"}, "8-12": {"targets": "מדבר/ת עם מבוגר על הציפיות לפני מפגש ועל מה שהרגיש/ה אחריו, ב-3 מתוך 4 מפגשים", "steps": ["לפני ← שאלה פתוחה: מה את/ה מצפה? מה מדאיג?", "אחרי ← מקשיבים, ומאפשרים אכזבה בלי לתקן"], "principles": "מאפשרים ציפייה ואכזבה", "sentences": ["מה את/ה מקווה שיהיה?", "זה מאכזב כשזה לא כמו שרצית"], "seen": "ציפיות גבוהות ואכזבות, מפגשים שבוטלו", "needs": "מקום לציפיות ולאכזבות", "why": "עיבוד ציפיות ואכזבות מפחית תגובות קיצון ומחזק ויסות", "why_staff": "אכזבה ממפגש שבוטל היא קשה מאוד. נשארים עם הילד/ה", "method": "TF-CBT: עיבוד רגשי"}}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, draft = true where public.mercury_library.content is null;
insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'goal', 'פרידה מאנשים וממקומות', 'להיפרד מאיש צוות שעוזב, מחבר או מהמרכז, בדרך טובה', array['אובדן ופרידה', 'היקשרות וקשר עם מבוגר', 'מעברים ושגרה']::text[], 'אובדן ופרידה', array['ARC', 'DDP/PACE', 'Theraplay']::text[], '{"bank": 1, "review": 1, "scale": ["מתפרק/ת או מתנתק/ת בפרידה", "מתקשה מאוד ונסגר/ת", "משתתף/ת בטקס פרידה בליווי", "אומר/ת מה מרגיש/ה על הפרידה", "נפרד/ת ושומר/ת זיכרון טוב"], "avoid": "לא להעלים איש צוות שעוזב בלי פרידה; לא להסתיר פרידה כדי לחסוך כאב", "strengths": ["אומץ", "קבלה"], "skills": [], "ages": {"2-5": {"targets": "משתתף/ת בטקס פרידה פשוט (ציור, תמונה משותפת) ומקבל/ת נחמה אחריו", "steps": ["כמה ימים לפני ← מספרים בפשטות שהמבוגר עוזב ומי יישאר", "טקס פרידה קטן: תמונה, ציור, חיבוק"], "principles": "פרידה גלויה, פשוטה ועם טקס", "sentences": ["עוד יומיים הוא נפרד מאיתנו. אנחנו נשארים", "בוא/י נכין לו ציור"], "seen": "מבולבל/ת, מחפש/ת את מי שעזב", "needs": "הסבר פשוט ונוכחות של מי שנשאר", "why": "פרידות לא מוסברות משחזרות אובדנים; פרידה מתווכת מתקנת", "why_staff": "פרידה מסודרת, גם אם עצובה, מלמדת שאנשים לא נעלמים סתם", "method": "Theraplay: טקסי פרידה"}, "5-8": {"targets": "אומר/ת מה מרגיש/ה על פרידה צפויה ומשתתף/ת בהכנת מתנת פרידה", "steps": ["מודיעים מראש ← לפחות שבוע לפני", "מכינים יחד מתנה או מכתב, ושומרים תמונה בקופסת זיכרונות"], "principles": "זמן להיפרד ודבר מוחשי לזכור", "sentences": ["איך את/ה מרגיש/ה שהיא עוזבת?", "אפשר להיות עצוב/ה ולזכור דברים טובים"], "seen": "כעס על מי שעוזב, או אדישות", "needs": "זמן להיפרד ולזכור", "why": "פרידה עם הכנה ומשמעות מאפשרת עיבוד במקום חוויית נטישה נוספת", "why_staff": "כשנותנים זמן להיפרד, הילד/ה לא מרגיש/ה ננטש/ת שוב", "method": "ARC – התקשרות: פרידה מתוכננת"}, "8-12": {"targets": "משתתף/ת בתכנון הפרידה (ממבוגר או מהמרכז) ומדבר/ת על רגשותיו/רגשותיה, לאורך תקופת הפרידה", "steps": ["משתפים בתכנון: מה היית רוצה שיקרה בפרידה?", "מכירים בכאב בלי למהר לנחם"], "principles": "שותפות וכנות", "sentences": ["מה היית רוצה שיהיה ביום האחרון?", "זה כואב, וזה הגיוני שכואב"], "seen": "מתרחק/ת מראש כדי לא להיפגע", "needs": "שותפות וכנות", "why": "התרחקות מקדימה היא הגנה מפני אובדן; שותפות בפרידה מאפשרת עיבוד", "why_staff": "כשילד/ה מתרחק/ת לפני פרידה, זה כדי לא להיפגע. נשארים קרובים", "method": "DDP/PACE: אמפתיה וכנות"}}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, draft = true where public.mercury_library.content is null;
insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'goal', 'שמירה על זיכרונות ורצף', 'לשמור זיכרונות טובים ולהרגיש שהסיפור שלי ממשיך', array['אובדן ופרידה', 'זהות ודימוי עצמי']::text[], 'אובדן ופרידה', array['TF-CBT', 'ARC']::text[], '{"bank": 1, "review": 3, "scale": ["אין זיכרונות שמורים, הכל מתפזר", "שומר/ת חפץ אחד", "משתתף/ת בקופסת זיכרונות עם מבוגר", "מוסיף/ה לקופסה ביוזמתו/ביוזמתה", "מספר/ת סיפורים טובים מהעבר ומהמרכז"], "avoid": "לא לזרוק ציורים, תמונות או חפצים אישיים בלי לשאול", "strengths": ["יצירתיות", "אחריות"], "skills": [], "ages": {"2-5": {"targets": "מוסיף/ה ציור או תמונה לקופסת הזיכרונות עם מבוגר, פעם בשבוע", "steps": ["לכל ילד/ה קופסת זיכרונות ← פעם בשבוע מוסיפים משהו", "מסתכלים יחד בקופסה ומספרים"], "principles": "שומרים, מסתכלים, מספרים", "sentences": ["בוא/י נשים את הציור בקופסה שלך", "זוכר/ת כשציירת את זה?"], "seen": "חפצים הולכים לאיבוד, אין רצף", "needs": "מקום לזיכרונות", "why": "תיעוד מוחשי יוצר רצף זהותי לילדים שעברו מעברים רבים", "why_staff": "קופסת זיכרונות עוזרת לילד/ה להרגיש שיש לו/לה סיפור", "method": "ARC – מסוגלות: זהות ורצף"}, "5-8": {"targets": "משתתף/ת בספר החיים או בקופסת הזיכרונות ומספר/ת על זיכרון טוב, פעמיים בחודש", "steps": ["מצלמים רגעים טובים במרכז (לפי הנוהל) ← מדפיסים לקופסה", "מספרים יחד סיפורים טובים מהשבוע"], "principles": "מתעדים את הטוב", "sentences": ["איזה רגע טוב נשמור השבוע?", "תראה/תראי כמה דברים טובים עשית"], "seen": "זוכר/ת בעיקר דברים רעים", "needs": "תיעוד של רגעים טובים", "why": "חיזוק זיכרונות חיוביים מאזן הטיה שלילית בנרטיב העצמי", "why_staff": "כשאוספים רגעים טובים, הילד/ה זוכר/ת שיש גם טוב", "method": "TF-CBT: נרטיב ואיזון"}, "8-12": {"targets": "מנהל/ת בעצמו/בעצמה תיק זיכרונות או ספר חיים ומשתף/ת בו מבוגר, לאורך 3 חודשים", "steps": ["תיק אישי שהילד/ה אחראי/ת עליו ← המבוגר עוזר לשמור", "מדי פעם ← מדפדפים יחד ומדברים על הדרך שעבר/ה"], "principles": "הבעלות אצל הילד/ה", "sentences": ["מה תרצה/תרצי להוסיף לתיק?", "עברת דרך ארוכה"], "seen": "תחושת חוסר המשכיות, עבר מקוטע", "needs": "בעלות על הסיפור", "why": "בעלות על הנרטיב מחזקת זהות קוהרנטית ותחושת שליטה", "why_staff": "התיק שייך לילד/ה. אנחנו עוזרים לשמור עליו", "method": "TF-CBT: נרטיב חיים"}}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, draft = true where public.mercury_library.content is null;
insert into public.mercury_library (scope, kind, title, description, themes, category, content, draft) values ('mercury', 'avoid', 'ממה להימנע – אובדן ופרידה', 'לא לדבר רע על ההורים. לא לשאול שאלות חוקרות אחרי מפגש. לא להסתיר פרידה צפויה.', array['אובדן ופרידה']::text[], 'אובדן ופרידה', '{"bank": 1, "ages": {"2-5": "לא להעלים מבוגר בלי פרידה. לא להבטיח מפגש שלא ידוע. לא לזרוק ציורים וחפצים אישיים.", "5-8": "לא לדבר רע על ההורים. לא לשאול שאלות חוקרות אחרי מפגש. לא להסתיר פרידה צפויה.", "8-12": "לא לבחור צד בין הילד/ה למשפחה. לא למהר לנחם על אובדן. לא לבטל את הרגשות המעורבים."}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, draft = true where public.mercury_library.content is null;
insert into public.mercury_library (scope, kind, title, description, themes, category, content, draft) values ('mercury', 'signs', 'אותות מוקדמים – אובדן ופרידה', 'התפרצויות לפני או אחרי שיחות ומפגשים, עצב, שאלות על הבית.', array['אובדן ופרידה']::text[], 'אובדן ופרידה', '{"bank": 1, "ages": {"2-5": "בכי בערב, חיפוש ההורים, נסיגה (הרטבה, מציצה), נצמד/ת.", "5-8": "התפרצויות לפני או אחרי שיחות ומפגשים, עצב, שאלות על הבית.", "8-12": "אדישות מופגנת, התרחקות לפני פרידות, כעס על מי שעוזב."}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, draft = true where public.mercury_library.content is null;
insert into public.mercury_library (scope, kind, title, description, themes, category, content, draft) values ('mercury', 'calm', 'מה עוזר להירגע – אובדן ופרידה', 'לצייר או לכתוב למשפחה, קופסת הזיכרונות, משחק אהוב. משפט: הגעגוע אומר שאת/ה אוהב/ת.', array['אובדן ופרידה']::text[], 'אובדן ופרידה', '{"bank": 1, "ages": {"2-5": "חיבוק, תמונה של המשפחה (אם אושר), חפץ מעבר, שיר. משפט: מותר להתגעגע, אני פה איתך.", "5-8": "לצייר או לכתוב למשפחה, קופסת הזיכרונות, משחק אהוב. משפט: הגעגוע אומר שאת/ה אוהב/ת.", "8-12": "שיחה בלי שיפוט, זמן לבד בטווח ראייה, התיק האישי. משפט: זה כואב, וזה הגיוני."}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, draft = true where public.mercury_library.content is null;
insert into public.mercury_library (scope, kind, title, description, themes, category, content, draft) values ('mercury', 'routine', 'שגרה – אובדן ופרידה', 'תכנון האחרי לפני כל מפגש. הודעה מראש על פרידות. קופסת זיכרונות.', array['אובדן ופרידה']::text[], 'אובדן ופרידה', '{"bank": 1, "ages": {"2-5": "טקס חזרה אחרי מפגשים. קופסת זיכרונות שמתעדכנת פעם בשבוע.", "5-8": "תכנון האחרי לפני כל מפגש. הודעה מראש על פרידות. קופסת זיכרונות.", "8-12": "שיחה לפני ואחרי מפגשים. תיק זיכרונות אישי. שותפות בתכנון פרידות."}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, draft = true where public.mercury_library.content is null;
insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'plan', 'תכנית: אובדן ופרידה', '[שם] מתמודד/ת עם געגוע ופרידות, וזה מתבטא ב[איך זה נראה]. כרגע הכי חשוב לתת ל[שם] מקום להתגעגע, ליווי סביב מפגשים ושיחות, ופרידות מסודרות. [מה כבר עוזר].', array['אובדן ופרידה']::text[], 'אובדן ופרידה', array['DDP/PACE', 'TF-CBT']::text[], '{"bank": 1, "summary": "[שם] מתמודד/ת עם געגוע ופרידות, וזה מתבטא ב[איך זה נראה]. כרגע הכי חשוב לתת ל[שם] מקום להתגעגע, ליווי סביב מפגשים ושיחות, ופרידות מסודרות. [מה כבר עוזר].", "goal_titles": ["ביטוי געגוע למשפחה", "התמודדות עם מפגשים ושיחות עם המשפחה", "פנייה למבוגר בטוח"], "parts": {"avoid": "ממה להימנע – אובדן ופרידה", "signs": "אותות מוקדמים – אובדן ופרידה", "calm": "מה עוזר להירגע – אובדן ופרידה", "routine": "שגרה – אובדן ופרידה"}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, draft = true where public.mercury_library.content is null;
